function addLog(message){const entry=document.createElement('div');entry.className='log-entry';entry.textContent=message;$('log-box').prepend(entry)}
function playerArmies(){return state.armies.filter(a=>a.owner===state.playerFaction)}
const UNIT_SHORT={INFANTRY:'🛡️보병',ARCHER:'🏹궁병',HEAVY_INFANTRY:'🛡️중보병',CAVALRY:'🐎기병'};
function compositionText(army){army.composition??={[army.unitType||'INFANTRY']:army.troops};const total=Math.max(1,Object.values(army.composition).reduce((sum,count)=>sum+count,0)),parts=Object.entries(army.composition).filter(([,count])=>count>0).map(([type,count])=>`${UNIT_SHORT[type]||UNIT_TYPES[type]?.label||'Unit'} ${count.toLocaleString()} (${Math.round(count*100/total)}%)`);return parts.join(' | ')||'?'}
function adjustComposition(army,delta){army.composition??={[army.unitType||'INFANTRY']:army.troops};for(const[type,count]of Object.entries(delta)){if(count>=0)army.composition[type]=(army.composition[type]||0)+count;else{let loss=-count,primary=Math.min(army.composition[type]||0,loss);army.composition[type]=(army.composition[type]||0)-primary;loss-=primary;for(const other of Object.keys(army.composition)){if(!loss)break;if(other===type)continue;const take=Math.min(army.composition[other],loss);army.composition[other]-=take;loss-=take}}}}
function assignGeneralToArmy(army,slot,generalId){for(const other of state.armies){if(other!==army){if(other.commanderId===generalId)other.commanderId=null;if(other.subCommanderId===generalId)other.subCommanderId=null}}if(state.supremeCommanderId===generalId)state.supremeCommanderId=null;if(slot==='commanderId'&&army.subCommanderId===generalId)army.subCommanderId=null;if(slot==='subCommanderId'&&army.commanderId===generalId)army.commanderId=null;army[slot]=generalId||null;renderAll()}
function assignSupremeCommander(generalId){for(const army of state.armies){if(army.commanderId===generalId)army.commanderId=null;if(army.subCommanderId===generalId)army.subCommanderId=null}state.supremeCommanderId=generalId||null;state.commanderBonusByFaction??={};const general=state.generals.find(g=>g.id===generalId);state.commanderBonusByFaction[state.playerFaction]=general?1+(general.leadership+general.intellect)/1200:1;addLog(`${general?.name||'총사령관 없음'}을(를) 국군 총사령관으로 임명했습니다. 전군 통솔·보급 지휘 효과가 적용됩니다.`);renderAll()}
