function displaySpeaker(name,sceneId=''){if(/백제.*사신/.test(name))return "백제 상좌평 · 사비 사절 '사법명'";if(/신라.*사신/.test(name))return "신라 대아찬 · 금성 사절 '거칠부'";if(/매복.*지휘관|지휘관.*매복/.test(name))return "신라 삼년산성 군주 · 장군 '고간(도도)'";return name}
function displayEmotion(tag){const labels={neutral:'😐 담담한 어조',ambitious:'🦊 야심을 감추지 못하며',determined:'⚔️ 결의를 다지며',relieved:'😌 안도하며',bitter:'😠 쓰라림을 삼키며 날 선 목소리로',sad:'😔 침통한 기색',angry:'😠 분노를 억누르지 못하고',shout:'🔥 격앙된 외침',resigned:'😮‍💨 체념한 듯 낮게',whisper:'🤫 숨죽여 속삭이며',worried:'😟 불안을 감추지 못하고',excited:'✨ 들뜬 기색',surprised:'😮 놀라 숨을 삼키며',grateful:'🙏 고마움을 담아'};return String(tag).replace(/[\[\]]/g,'').split(/[→>]/).map(part=>labels[part.trim().toLowerCase()]||'😐 담담한 어조').join(' → ')}
