function showCutsceneSillaHalf(){const id='CS-04',scene=CUTSCENES[id],choices=$('cutscene-choices');$('cutscene-kicker').textContent='관산성의 밤';$('cutscene-title').textContent=scene.title;const storyLines=state.quests.seongwangChoice==='ABSENT'?[['\uC5EC\uCC3D','whisper','...\uBC84\uD2F8 \uC218\uAC00 \uC5C6\uB2E4. \uC9C0\uC6D0\uC774 \uC624\uC9C0 \uC54A\uC73C\uBA74.'],['\uC804\uB839','shout','\uC804\uD558\uAED8\uC11C\uB294 \uD6C4\uBC29\uC5D0 \uB0A8\uC73C\uC2DC\uACE0, \uC815\uC608 \uD638\uC704\uB9CC \uBCF4\uB0B4\uC168\uC2B5\uB2C8\uB2E4!'],['\uC5EC\uCC3D','sad','\uC544\uBC84\uB2D8\uC740 \uC6C5\uC9C4\uC5D0\uC11C \uAD70\uB7C9\uACFC \uC99D\uC6D0\uC744 \uBAA8\uC73C\uACE0 \uACC4\uC2E0\uB2E4. \uC774 \uC804\uD22C\uB294 \uB0B4\uAC00 \uB05D\uB0B4\uACA0\uB2E4.'],['\uC2E0\uB77C \uC0BC\uB144\uC0B0\uC131 \uAD70\uC8FC \uC7A5\uAD70 \uACE0\uAC04(\uB3C4\uB3C4)','neutral','\uC131\uC655\uC740 \uC624\uC9C0 \uC54A\uC558\uB2E4. \uD0DC\uC790\uB97C \uB193\uCE60 \uC218\uB294 \uC5C6\uB2E4.']]:scene.lines;const lineBox=$('cutscene-lines');lineBox.replaceChildren(...storyLines.map(([speaker,mood,text])=>{const div=document.createElement('div');div.className='dialogue-line';div.dataset.mood=(mood.split(/[?>]/).at(-1)||"neutral").toLowerCase();div.innerHTML=`<span class="speaker">${escapeHtml(displaySpeaker(speaker,id))}</span><br>${escapeHtml(text)}`;return div}));const silaChoices=state.quests.seongwangChoice==='ABSENT'?[['A','\uC131\uC655\uC758 \uD6C4\uBC29 \uC794\uB958\uB97C \uD655\uC778\uD558\uACE0 \uC804\uD22C\uB97C \uACB0\uC0B0\uD55C\uB2E4','SPARED']]:scene.sillaChoices;choices.replaceChildren(...silaChoices.map(([letter,label,value])=>{const button=document.createElement('button');button.textContent=`${({A:'🅰️',B:'🅱️',C:'🅲️'}[letter]||letter)} · ${label}`;button.dataset.tooltip=value==='CAPTURED'?UI_LABELS.tooltipCutsceneCapture:value==='DIES'?UI_LABELS.tooltipCutsceneDeath:UI_LABELS.tooltipCutsceneSpare;const preview=document.createElement('small');preview.className='choice-preview';preview.textContent='👉 '+button.dataset.tooltip.split(/\n/).map(x=>x.replace(/^[^:]+:\s*/, '')).join(' · ');button.append(preview);button.removeAttribute("data-tooltip");button.onclick=()=>finishGwansan(state.quests.seongwangChoice||'ATTEND',value);return button}));setupCutscenePages('CS-04-SILLA',true)}
function closeCutscene(){if(activeReadOnlyCutscene){$('cutscene-modal').close();if(readOnlyCutsceneSnapshot){state.quests.scenePage=readOnlyCutsceneSnapshot.scenePage;state.quests.pendingScene=readOnlyCutsceneSnapshot.pendingScene;state.quests.readOnlyScene=readOnlyCutsceneSnapshot.readOnlyScene;state.eventOpen=readOnlyCutsceneSnapshot.eventOpen}readOnlyCutsceneSnapshot=null;activeReadOnlyCutscene=false;return}const id=state.quests.pendingScene;if(id?.startsWith('CS-'))state.quests.cutscenes.add(id);$('cutscene-modal').close();state.quests.pendingScene=null;state.quests.sideScene=null;state.eventOpen=false;renderAll();queueMicrotask(pumpStoryQueue)}function replayCutscene(id){if(!state.quests.cutscenes.has(id)||activeReadOnlyCutscene)return;readOnlyCutsceneSnapshot={scenePage:state.quests.scenePage,pendingScene:state.quests.pendingScene,readOnlyScene:state.quests.readOnlyScene,eventOpen:state.eventOpen};activeReadOnlyCutscene=true;renderCutscene(id,true)}
function renderStoryArchive(){const box=$('story-archive');if(!box)return;const names={'CS-01':'맹약의 자리','CS-01-G':'남경의 경보','CS-G2':'나제동맹 균열과 밀약','CS-G3':'단양·웅진 남진 역습','CS-G4':'삼한 패권의 결산','CS-02-S':'한강 하류의 결단','CS-02-B':'믿은 자의 자리','CS-04':'관산성의 밤'};const ids=[...state.quests.cutscenes].filter(id=>CUTSCENES[id]).sort();box.replaceChildren();if(!ids.length){box.innerHTML='<p class="empty-armies">아직 열람할 이야기가 없습니다.</p>';return}for(const id of ids){const button=document.createElement('button');button.className='archive-entry';button.textContent=names[id]||'역사의 한 장면';button.onclick=()=>replayCutscene(id);box.append(button)}}
const SIDEQUEST_DIALOGUE={
  'SQ-01':['육두품 인재','neutral','율령은 백성을 하나로 묶으나, 골품의 벽은 아직 높사옵니다. 재능 있는 자를 조정에 들이시겠습니까?'],
  'SQ-02':['담로 사신','neutral','왕족을 지방에 보내 다스릴지, 교역 허가로 민심을 얻을지 결정해 주십시오.'],
  'SQ-03':['대가야 수장','whisper→worried','두 나라에 서로 다른 약속을 했소. 밀서를 감추면 가야가 숨을 돌리지만, 한쪽에 내보이면 다른 쪽은 등을 돌릴 것이오.'],
  'SQ-04':['고구려 밀사','whisper','한강의 형세가 기울고 있소. 밀약으로 서로의 칼끝을 거두겠소, 아니면 제안을 거부하겠소?'],
  'SQ-05':['젊은 무관','excited','첫 전장에 나설 준비가 되었습니다. 이사부 장군의 훈련을 더 받을지, 선봉에 설지 명해 주십시오.']
};
function renderSideQuestEvent(id){const quest=SIDE_QUESTS.find(item=>item.id===id),script=SIDE_QUEST_SCRIPTS[id];if(!quest||!script){state.eventOpen=false;return}const confirmOnly=id==='SQ-04'&&Boolean(state.quests.goguryeoPactDecision);state.quests.sideScene={id,page:1,choiceId:null,confirmOnly};renderSideQuestPage(id)}
function renderSideQuestPage(id){const quest=SIDE_QUESTS.find(item=>item.id===id),script=SIDE_QUEST_SCRIPTS[id],scene=state.quests.sideScene;if(!quest||!script||!scene)return;const context=$('cutscene-context'),box=$('cutscene-lines'),choices=$('cutscene-choices'),next=$('btn-cutscene-continue'),skip=$('btn-cutscene-skip');$('cutscene-kicker').textContent='행동 사건';$('cutscene-title').textContent=scene.confirmOnly?'태학의 문서 · 이미 내린 결정을 확인합니다':quest.title;context.hidden=scene.page!==1;context.textContent=scene.confirmOnly?`앞선 ${state.quests.goguryeoPactDecisionSource==='CS-G2'?'제가회의의 결정':'태학 밀약 사건'}에서 ${state.quests.goguryeoPactDecision==='PACT'?'밀약을 수락':'밀약을 거부'}했습니다. 이 장면은 같은 사건의 후속 단계이며 결정을 바꾸거나 보상을 다시 지급하지 않습니다.`:script.background;box.hidden=scene.page!==2&&scene.page!==4;choices.hidden=scene.page!==3;box.replaceChildren();if(scene.page===2){const lines=scene.confirmOnly?GOGURYEO_PACT_CONFIRMATION[state.quests.goguryeoPactDecision]:script.dialogue;for(const [speaker,mood,text]of lines){const line=document.createElement('div');line.className='dialogue-line';line.dataset.mood=(mood.split(/[?>]/).at(-1)||'neutral').toLowerCase();line.innerHTML=`<span class="speaker">${escapeHtml(speaker)}</span><br>${escapeHtml(text)}`;box.append(line)}}if(scene.page===4){for(const [speaker,mood,text]of (script.reactions[scene.choiceId]||[])){const line=document.createElement('div');line.className='dialogue-line';line.dataset.mood=(mood.split(/[?>]/).at(-1)||'neutral').toLowerCase();line.innerHTML=`<span class="speaker">${escapeHtml(speaker)}</span><br>${escapeHtml(text)}`;box.append(line)}}choices.replaceChildren();if(scene.page===3&&!scene.confirmOnly){choices.replaceChildren(...quest.choices.map((choice,index)=>{const button=document.createElement('button');const [action,effect=''] = choice.label.split(' · ',2);button.textContent=`${index===0?'🅰️':'🅱️'} · ${action.replace(/GOGURYEO_pact\s*=\s*TRUE/i,'밀약을 수락한다').replace(/GOGURYEO_pact\s*=\s*FALSE/i,'밀약을 거부한다')}`;const detail=document.createElement('small');detail.className='choice-preview';detail.textContent=`선택 결과: ${effect.replace(/GOGURYEO_pact\s*=\s*TRUE/i,'밀약 성립').replace(/GOGURYEO_pact\s*=\s*FALSE/i,'밀약 거부')} · ${choice.epilogue}`;button.append(detail);button.onclick=()=>{if(!applySideQuest(id,choice.id,true))return;scene.choiceId=choice.id;scene.page=4;renderAll();renderSideQuestPage(id)};return button}))}if(scene.page===3&&scene.confirmOnly){const button=document.createElement('button');button.textContent='기존 결정을 확인하고 반응을 듣는다';button.onclick=()=>{scene.choiceId=state.quests.goguryeoPactDecision==='PACT'?'accept':'refuse';scene.page=4;renderSideQuestPage(id)};choices.append(button)}next.style.display=scene.page===3&&!scene.confirmOnly?'none':'inline-block';next.textContent=scene.page===4||scene.page===3?'대화 마치기':'다음 장 ▶';next.onclick=()=>{if(scene.page<3){scene.page++;renderSideQuestPage(id);return}if(scene.page===3&&scene.confirmOnly){scene.choiceId=state.quests.goguryeoPactDecision==='PACT'?'accept':'refuse';scene.page=4;renderSideQuestPage(id);return}closeCutscene()};skip.style.display=!scene.confirmOnly&&(scene.page===1||scene.page===2)?'inline-block':'none';skip.textContent='건너뛰기(선택지로)';skip.onclick=()=>{scene.page=3;renderSideQuestPage(id)};$('btn-cutscene-close').style.display='none';if(!$('cutscene-modal').open)$('cutscene-modal').showModal()}
function setTrust(value){state.trust=Math.max(0,Math.min(100,value));if(state.trust<=40){setRelation(state,'SILLA','BAEKJE','WAR');state.allianceBroken=true}checkActionTriggers('trust')}
function finishTreaty(value){state.flags.treatyClarity=value;setTrust(value==='HIGH'?70:value==='LOW'?60:65);chronicle('MQ-01',value,`TREATY_clarity=${value}; trust ${state.trust}`);state.quests.path.push(`CS-01 맹약: ${value}`);state.quests.completed.add('MQ-01');state.quests.cutscenes.add('CS-01');$('cutscene-modal').close();state.quests.pendingScene=null;state.quests.mainIndex=1;state.eventOpen=false;addLog(`협정 분기 확정: TREATY_clarity=${value}, 신뢰 ${state.trust}.`);renderAll();queueMicrotask(pumpStoryQueue)}
function showGoguryeoReaction(sceneId,value){const reactionKey=sceneId==='CS-G2'&&value==='CONFIRM'?(state.quests.goguryeoPactDecision==='PACT'?'PACT':'REFUSE'):value;const lines=GOGURYEO_REACTIONS[sceneId]?.[reactionKey]||[];$('cutscene-kicker').textContent='선택 직후의 반응';$('cutscene-title').textContent='결정의 여파';$('cutscene-context').hidden=true;const box=$('cutscene-lines');box.hidden=false;box.replaceChildren(...lines.map(([speaker,mood,text])=>{const div=document.createElement('div');div.className='dialogue-line';div.dataset.mood=(mood.split(/[?>]/).at(-1)||'neutral').toLowerCase();div.innerHTML=`<span class="speaker">${escapeHtml(displaySpeaker(speaker,sceneId))}</span><span class="mood">${escapeHtml(displayEmotion(mood))}</span><br>${escapeHtml(text)}`;return div}));$('cutscene-choices').hidden=true;$('cutscene-choices').replaceChildren();$('cutscene-page-indicator').hidden=true;$('btn-cutscene-skip').style.display='none';const next=$('btn-cutscene-continue');next.style.display='inline-block';next.textContent='대화 마치기';next.onclick=()=>{const ending=state.quests.goguryeoEndingPending;state.quests.goguryeoEndingPending=null;closeCutscene();if(ending){state.quests.ending=ending;showEnding()}}}
function finishGoguryeoChoice(sceneId,value){if(sceneId==='CS-G2'&&value==='CONFIRM'){const decision=state.quests.goguryeoPactDecision;if(!decision)return;chronicle('MQ-G2','기존 밀약 결정 확인',`CS-G2_CONFIRM=${decision}`);state.quests.path.push(`CS-G2: 기존 결정 확인 (${decision==='PACT'?'수락':'거부'})`);state.quests.completed.add('MQ-G2');state.quests.mainIndex=2;state.triggers.goguryeoNextTurn=state.turn+1;state.quests.cutscenes.add(sceneId);addLog(`고구려 밀약의 기존 ${decision==='PACT'?'수락':'거부'} 결정을 확인했습니다. 보상은 다시 지급되지 않았습니다.`);renderAll();showGoguryeoReaction(sceneId,'CONFIRM');return}chronicle(`MQ-G${state.quests.mainIndex+1}`,value,`${sceneId}=${value}`);state.quests.path.push(`${sceneId}: ${value}`);if(sceneId==='CS-01-G'){state.goguryeoStance=value;if(value==='DEFENSE'){state.defenseBonus=1.3;state.attackBonus=1}else if(value==='OFFENSE'){state.attackBonus=1.3;state.defenseBonus=1}else{state.quests.unlockedPact=true}state.quests.completed.add('MQ-G1');state.quests.cutscenes.add(sceneId);state.quests.mainIndex=1;state.triggers.goguryeoNextTurn=state.turn+1}else if(sceneId==='CS-G2'){state.flags.goguryeoPact=value==='PACT';state.quests.goguryeoPactDecision=value;state.quests.goguryeoPactDecisionSource='CS-G2';state.quests.completed.add('MQ-G2');state.quests.mainIndex=2;state.triggers.goguryeoNextTurn=state.turn+1}else if(sceneId==='CS-G3'){state.quests.goguryeoCounterTarget=value;state.quests.completed.add('MQ-G3');state.quests.mainIndex=3;state.triggers.goguryeoNextTurn=state.turn+1}else{state.quests.completed.add('MQ-G4');state.quests.mainIndex=4;state.quests.goguryeoEndingPending={id:value,title:value==='HEGEMONY'?'삼한 패권 회복':value==='BALANCE'?'제가회의의 균형':'한강 방어선의 승리',summary:'양원왕과 제가회의가 선택한 방책이 고구려의 다음 시대를 결정했습니다.'}}state.quests.cutscenes.add(sceneId);state.quests.pendingScene=sceneId;addLog(`고구려 전용 임무 ${sceneId} 선택: ${value}`);renderAll();showGoguryeoReaction(sceneId,value)}
function finishRaid(value){chronicle('MQ-02',value,`SILLA_raid_scope=${value}`);state.flags.sillaRaidScope=value;setTrust(value==='FULL'?25:58);state.quests.path.push(`CS-02-S 신라 선택: ${value}`);if(value==='FULL'){const tile=findTileByNodeId(state,'danghang');if(tile){const oldOwner=tile.owner;tile.owner='SILLA';onTileCaptured(oldOwner,'SILLA',tile,null)}state.allianceBroken=true;setRelation(state,'SILLA','BAEKJE','WAR');state.hanseongTrigger=true;for(const army of state.armies.filter(a=>a.owner==='BAEKJE'))army.ap=0;addLog('신라가 한강 하류를 전부 취했습니다. 백제와의 동맹이 파기되고 관산성 방면 적대 진격이 시작됩니다.')}else if(value==='DELEGATE'){state.flags.sillaRaidScope='PARTIAL';state.isabuRelation=Math.min(100,state.isabuRelation+15)}state.quests.completed.add('MQ-02');state.quests.cutscenes.add('CS-02-S');$('cutscene-modal').close();state.quests.pendingScene=null;state.quests.mainIndex=2;state.eventOpen=false;addLog(`SILLA_raid_scope=${state.flags.sillaRaidScope}.`);renderAll()}
function finishBaekjeResponse(value){chronicle('MQ-02',value,`BAEKJE_response=${value}`);state.flags.baekjeResponse=value;setTrust(value==='PREEMPT'?55:value==='IGNORE'?35:45);if(value==='DELEGATE')state.isabuRelation=Math.min(100,state.isabuRelation+10);state.quests.path.push(`CS-02-B 백제 선택: ${value}`);state.quests.completed.add('MQ-02');state.quests.cutscenes.add('CS-02-B');$('cutscene-modal').close();state.quests.pendingScene=null;state.quests.mainIndex=2;state.eventOpen=false;addLog(`BAEKJE_response=${value}.`);renderAll()}
function finishGwansan(kingChoice,action){const outcome=kingChoice==='ABSENT'?'KING_ABSENT':({CAPTURED:'KING_CAPTURED',DIES:'KING_DIES',SPARED:'KING_SPARED'}[action]||action);state.flags.gwansanOutcome=outcome;state.quests.seongwangAlive=outcome!=='KING_DIES';state.quests.yeochangAlive=state.quests.yeochangAlive!==false;state.quests.yeochangSucceeded=outcome==='KING_DIES'&&state.quests.yeochangAlive;chronicle('MQ-04',`${kingChoice} / ${action}`,`GWANSAN_outcome=${outcome}`);state.quests.path.push(`CS-04 성왕 ${kingChoice} × 신라 ${action} → ${outcome}`);state.quests.completed.add('MQ-04');state.quests.cutscenes.add('CS-04');$('cutscene-modal').close();state.quests.pendingScene=null;state.quests.mainIndex=4;state.eventOpen=false;state.quests.ending=chooseEnding();addLog(`GWANSAN_outcome=${outcome}. 선택의 결산: ${state.quests.ending.title}`);renderAll();showEnding()}
function showEnding(){const ending=state.quests.ending;if(!ending)return;const epilogueKey=({DEFEND:'G-DEFEND',HEGEMONY:'G-HEGEMONY',BALANCE:'G-BALANCE'})[ending.id]||ending.id,epilogue=ENDING_EPILOGUES[epilogueKey];let settlement=epilogue?.settlement||ending.summary;if(epilogueKey==='G-HEGEMONY'){const target=state.quests.goguryeoCounterTarget==='DANYANG'?'danyang':state.quests.goguryeoCounterTarget==='UNGJIN'?'ungjin':null,tile=target?findTileByNodeId(state,target):null,place=state.quests.goguryeoCounterTarget==='DANYANG'?'단양 적성':state.quests.goguryeoCounterTarget==='UNGJIN'?'웅진':null;settlement+=!place?' 단양·웅진 중 진군 목표가 저장되어 있지 않아 특정 지역 점령을 단정하지 않습니다.':tile?.owner==='GOGURYEO'?` ${place} 점령은 확인된 전과입니다.`:` ${place}은 진군 목표였으며 실제 점령 여부는 확인되지 않았습니다.`}$('ending-title').textContent=`${ending.hidden?'히든 엔딩 · ':`엔딩 ${ending.id} · `}${ending.title}`;const sections=[`<div class="ending-outcome"><h3>정세 결산</h3><p>${escapeHtml(settlement)}</p></div>`];if(epilogue){sections.push(`<section class="ending-essay"><h3>가상 사론</h3><p><b>창작 사론 — 실제 《삼국사기》 인용이 아닙니다.</b></p><p>史論曰: ${escapeHtml(epilogue.essay)}</p></section>`);if(['A','C'].includes(epilogueKey)&&state.quests.seongwangAlive===false&&state.quests.yeochangAlive===true&&state.quests.yeochangSucceeded===true)sections.push('<p class="succession-note"><b>태자 여창은 성왕의 뒤를 이어 즉위해 위덕왕이 됩니다.</b></p>');const people=epilogue.people.filter(([name])=>{if(name==='성왕')return epilogueKey==='H-NORTH'?state.quests.seongwangAlive===true:state.quests.seongwangAlive===false;if(name==='성왕 (생존 시)'||name==='성왕(생존)')return state.quests.seongwangAlive===true;if(name==='태자 여창')return state.quests.seongwangAlive===false?state.quests.yeochangAlive===true&&state.quests.yeochangSucceeded===true:state.quests.yeochangAlive!==false;return true});sections.push(`<section class="ending-people"><h3>인물별 후일담</h3><ul>${people.map(([name,text])=>`<li><b>${escapeHtml(name)}</b> — ${escapeHtml(text)}</li>`).join('')}</ul></section>`)}const sq01=state.quests.sq01ChoiceId?`SQ-01 선택 ${state.quests.sq01ChoiceId} · ${state.quests.sq01Survives}`:'SQ-01 인물 경로 미선택',sq05=state.quests.sq05ChoiceId?`SQ-05 선택 ${state.quests.sq05ChoiceId} · ${state.quests.sadahamAlive===true?'사다함 생존':'사다함 전사'}`:'SQ-05 인물 경로 미선택';sections.push(`<section class="ending-quests"><h3>사이드 퀘스트 후일담</h3><p>${escapeHtml(sq01)}</p><p>${escapeHtml(sq05)}</p></section>`);sections.push(`<div class="ending-path"><b>선택 경로</b><br>${state.quests.path.map(escapeHtml).join('<br>')||'기록된 선택 없음'}</div>`);$('ending-summary').innerHTML=sections.join('');$('ending-modal').showModal()}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]))}
function chooseEnding(){const f=state.flags;if(f.goguryeoPact&&f.gwansanOutcome!=='KING_DIES')return{id:'H-NORTH',title:'북방의 그림자',hidden:true,summary:'고구려와의 암묵적 밀약으로 신라가 전력을 아껴 우위를 얻습니다. 이 진실은 역사에 기록되지 않습니다.'};if(f.gayaFavorBaekje>=40&&f.gayaFavorSilla>=40)return{id:'H-IRON',title:'쇠의 나라',hidden:true,summary:'대가야는 두 강국 어디에도 완전히 흡수되지 않고 교역 거점으로 독자 지위를 지킵니다.'};if(f.treatyClarity==='NONE'&&f.sillaRaidScope==='FULL'&&f.gwansanOutcome==='KING_DIES')return{id:'C',title:'끊어진 저울',summary:'신뢰가 무너진 두 나라는 소모전에 묶이고 가야는 그 틈에서 흡수되거나 고립됩니다.'};if(f.treatyClarity==='HIGH'&&f.sillaRaidScope==='PARTIAL'&&['KING_CAPTURED','KING_SPARED','KING_ABSENT'].includes(f.gwansanOutcome))return{id:'D',title:'유예된 전쟁',summary:'전면전은 피했지만 상처는 남았습니다. 두 나라의 갈등은 다음 세대의 숙제로 이어집니다.'};if(f.gwansanOutcome==='KING_DIES')return{id:'A',title:'중흥의 대가',summary:'성왕은 전사했으나 그 죽음이 백제를 한동안 결집시킵니다. 여창은 복수심을 안고 즉위합니다.'};if(f.sillaRaidScope==='FULL'&&f.gwansanOutcome!=='KING_SPARED')return{id:'B',title:'삼한의 설계자',summary:'신라는 한강을 완전히 장악하고 통일의 발판을 마련하지만, 신의 없는 왕이라는 평가도 남습니다.'};return{id:'D',title:'유예된 전쟁',summary:'양국은 상처를 안고 물러섭니다. 완전한 파국은 피했으나 갈등은 다음 세대에 남습니다.'}}
function applySideQuest(questId,choiceId,fromEvent=false){const quest=SIDE_QUESTS.find(q=>q.id===questId),choice=quest?.choices.find(c=>c.id===choiceId);state.quests.sideRewarded??=new Set();if(!quest||!choice||quest.faction!==state.playerFaction||state.quests.sideCompleted.has(questId)||state.quests.sideRewarded.has(questId)||(questId==='SQ-04'&&state.quests.goguryeoPactDecision))return false;state.quests.sideRewarded.add(questId);state.quests.sideCompleted.add(questId);const reward=choice.reward;if(reward.gold)state.nationalGold+=reward.gold;if(reward.troops){const army=playerArmies()[0];if(army){army.troops+=reward.troops;army.maxTroops+=reward.troops}else state.nationalFood+=reward.troops}if(reward.legitimacy)state.legitimacy=Math.min(100,state.legitimacy+reward.legitimacy);if(reward.trust)setTrust(state.trust+reward.trust);if(reward.gayaBaekje)state.flags.gayaFavorBaekje=Math.max(0,Math.min(100,state.flags.gayaFavorBaekje+reward.gayaBaekje));if(reward.gayaSilla)state.flags.gayaFavorSilla=Math.max(0,Math.min(100,state.flags.gayaFavorSilla+reward.gayaSilla));if('pact'in reward){state.flags.goguryeoPact=reward.pact;state.quests.goguryeoPactDecision=choiceId==='accept'?'PACT':'REFUSE';state.quests.goguryeoPactDecisionSource='SQ-04';}if(reward.isabu)state.isabuRelation=Math.min(100,state.isabuRelation+reward.isabu);if(questId==='SQ-01'){state.quests.sq01Survives=choice.epilogue;state.quests.sq01ChoiceId=choice.id}if(questId==='SQ-05'){state.quests.sq05Survives=choice.epilogue;state.quests.sq05ChoiceId=choice.id;state.quests.sadahamAlive=choice.survives===true}state.quests.path.push(`${questId} ${quest.title}: ${choice.label}`);chronicle(questId,choice.label,JSON.stringify(reward));if(fromEvent)state.eventQueue=state.eventQueue.filter(event=>!(event.type==='sidequest'&&event.id===questId));addLog(`${questId} 보상 적용: ${choice.label}`);renderAll();if(questId==='SQ-03'&&state.flags.gayaFavorBaekje>=40&&state.flags.gayaFavorSilla>=40)addLog('가야가 두 강국 사이의 독자 생존 기반을 확보했습니다.');return true}
function triggerSideQuest(id){const quest=SIDE_QUESTS.find(item=>item.id===id);if(!quest||quest.faction!==state.playerFaction||state.quests.sideCompleted.has(id)||state.quests.sideRewarded?.has(id))return;const key=id.replace('-','').toLowerCase();if(state.triggers[key]||state.quests.sideCompleted.has(id))return;state.triggers[key]=true;enqueueStoryEvent('sidequest',id)}
function checkActionTriggers(cause='turn'){
  if(!state.started)return;
  if(cause==='turn'&&state.triggers.sq01Turn!==null&&state.turn>=state.triggers.sq01Turn&&state.playerFaction==='SILLA')triggerSideQuest('SQ-01');
  if(state.playerFaction==='GAYA'&&(state.trust<=50||state.turn>=4))triggerSideQuest('SQ-03');
  if(state.playerFaction==='GOGURYEO'&&state.goguryeoTilesLost>0)triggerSideQuest('SQ-04');
  if(state.playerFaction==='GOGURYEO'&&state.triggers.goguryeoNextTurn&&state.turn>=state.triggers.goguryeoNextTurn){const next=['CS-G2','CS-G3','CS-G4'][state.quests.mainIndex-1];state.triggers.goguryeoNextTurn=null;if(next)showCutscene(next)}
}
function markStateAction(action){if(!state.started)return;if(action==='silla-policy'&&state.playerFaction==='SILLA')state.triggers.sq01Turn=state.turn+1;if(action==='baekje-rear'&&state.playerFaction==='BAEKJE')triggerSideQuest('SQ-02');if(action==='army-raised'&&state.playerFaction==='BAEKJE')triggerSideQuest('SQ-02');if(action==='goguryeo-policy'&&state.playerFaction==='GOGURYEO')state.defenseBonus=(state.defenseBonus||1)+.1;checkActionTriggers(action)}
function onTileCaptured(previousOwner,newOwner,tile,army){if(['SILLA','BAEKJE','GOGURYEO'].includes(previousOwner)&&previousOwner!==newOwner)state.collapseCaptors[previousOwner]=newOwner;if(state.playerFaction==='GOGURYEO'&&newOwner==='GOGURYEO'&&previousOwner!=='GOGURYEO'&&state.quests.mainIndex===2){state.quests.goguryeoSouthTargetCaptured=true;state.triggers.goguryeoNextTurn=state.turn+1}if(state.playerFaction==='GOGURYEO'&&previousOwner==='GOGURYEO'&&newOwner!=='GOGURYEO'){state.goguryeoTilesLost++;state.goguryeoHanseongLost ||= tile.node?.id==='hanseong';triggerSideQuest('SQ-04')}if(tile.node?.id==='hanseong'&&previousOwner!==newOwner&&!state.quests.completed.has('MQ-02')){state.hanseongTrigger=true;if(newOwner==='SILLA'&&state.playerFaction==='SILLA'){state.allianceBroken=true;setRelation(state,'SILLA','BAEKJE','WAR');setTrust(Math.min(state.trust,25))}if(state.playerFaction==='SILLA'||state.playerFaction==='BAEKJE')showCutscene(state.playerFaction==='BAEKJE'?'CS-02-B':'CS-02-S')}}
function onBattleResolved(attacker,defender,tile,isPlayerBattle){const nations=new Set([attacker.owner,defender.owner]);const sillaBaekje=nations.has('SILLA')&&nations.has('BAEKJE');const baekjeFinal=state.playerFaction==='BAEKJE'&&state.quests.mainIndex===3&&tile.node?.id==='gwansan',sillaFinal=state.playerFaction==='SILLA'&&(tile.node?.id==='gwansan'||tile.node?.type==='FORT');if((baekjeFinal||sillaFinal)&&sillaBaekje&&!state.quests.completed.has('MQ-04'))showCutscene('CS-04');const han=findTileByNodeId(state,'hanseong');if(sillaBaekje&&han&&getDistance(tile.q,tile.r,han.q,han.r)<=1)state.triggers.hanseongBattleTurn=state.turn+1;if(isPlayerBattle&&state.playerFaction==='SILLA'&&!state.triggers.sq05)triggerSideQuest('SQ-05')}

function renderLobby(){const cards=$('faction-cards');cards.replaceChildren();for(const factionId of ['SILLA','BAEKJE','GOGURYEO']){const info=FACTION_CAMPAIGNS[factionId],button=document.createElement('button');button.className=`faction-card ${state.lobbyFaction===factionId?'active':''}`;button.style.borderTop=`4px solid ${info.color}`;button.innerHTML=`<strong>${FACTIONS[factionId].name}</strong><span>${info.leader}</span>`;button.onclick=()=>{state.lobbyFaction=factionId;state.lobbyClanId=info.royalClan;renderLobby()};cards.append(button)}const info=FACTION_CAMPAIGNS[state.lobbyFaction];state.lobbyClanId=info.royalClan;$('lobby-faction-name').textContent=`${FACTIONS[state.lobbyFaction].name} · ${info.leader}`;$('lobby-faction-traits').textContent=info.traits;$('lobby-difficulty').textContent=info.difficulty;$('lobby-summary').textContent=`${councilNameFor(state.lobbyFaction)}와 시작 가문을 선택한 뒤 출진하세요.`;const clans=$('lobby-clan-options');clans.replaceChildren();for(const [id,label]of [[info.royalClan,'왕실'],[info.nobleClan,'대귀족']]){const clan=state.clans[id],button=document.createElement('button');const locked=id!==info.royalClan;button.className=`lobby-clan ${locked?'locked active':''}`;button.disabled=locked;button.innerHTML=`<b>${label} · ${clan.name}</b><br><small>${clan.leader} · 사병 ${clan.privateArmy.toLocaleString()}명</small>${locked?`<span class="lobby-lock-badge">${UI_LABELS.lobbyNobleLock}</span>`:''}`;if(!locked)button.onclick=()=>{state.lobbyClanId=id;renderLobby()};clans.append(button)}}
function councilNameFor(factionId){return COUNCILS[factionId]||'귀족 회의'}
function startCampaignLegacy(){if(state.started)return;const faction=state.lobbyFaction,campaign=FACTION_CAMPAIGNS[faction],start=FACTION_START[faction],army=state.armies.find(a=>a.id===start.army);state.playerFaction=faction;state.activeClanId=state.lobbyClanId;state.selectedTileKey=army?tileKey(army.q,army.r):start.tile;state.started=true;state.northWarApproved=faction==='GOGURYEO';state.tileCardOpen=false;if(army)army.clanId=state.lobbyClanId;$('campaign-lobby').close();$('ui-faction-badge').textContent=`${FACTIONS[faction].name} · ${campaign.leader}`;addLog(`${FACTIONS[faction].name} ${campaign.leader} 캠페인 시작. 시작 가문: ${state.clans[state.activeClanId].name}.`);renderAll();if(state.narrativeReady)showCutscene(faction==='GOGURYEO'?'CS-01-G':'CS-01')}
function startCampaign(){startCampaignLegacy();state.warAgendaApproved=false;state.northWarApproved=false;renderAll()}
function switchTab(tab){document.querySelectorAll('.side-tab').forEach(button=>button.classList.toggle('active',button.dataset.tab===tab));document.querySelectorAll('.tab-content').forEach(panel=>panel.classList.toggle('active',panel.dataset.panel===tab))}

function proposeWarAgenda(){if(!activeClan()?.isKing){addLog('왕실 가문으로 시작한 플레이어만 군사 의제를 상정할 수 있습니다.');return}if(state.northWarApproved){addLog('이미 군사 의제가 통과되었습니다.');return}if(state.warJustification<60){addLog('전쟁 명분 부족 ('+state.warJustification+'/60). 국제 정세 공작이나 국경 마찰이 필요합니다.');return}if(state.warJustification>=70&&state.nationalFood>=1200)for(const c of playerClans().filter(c=>!c.isKing&&!['gaya_kim','baekje_hae','baekje_jin','goguryeo_yakbu','park_noble','baekje_sa','goguryeo_go'].includes(c.id)))c.loyalty=Math.max(55,c.loyalty);openWarStrategy()}
function strategyPlans(){if(state.playerFaction==='SILLA')return[{label:'대고구려 북진 공동전선',detail:'백제와 나제동맹을 유지하고 고구려에 선전포고합니다.',wars:['GOGURYEO'],allies:[['SILLA','BAEKJE','ALLIANCE']]},{label:'고구려 밀약 & 백제 기습',detail:'고구려와 3턴 밀약을 맺고 백제를 기습합니다. 나제 신뢰도가 크게 하락합니다.',wars:['BAEKJE'],pacts:['GOGURYEO'],breakAlliance:true}];if(state.playerFaction==='BAEKJE')return[{label:'한성 고토 수복전',detail:'신라와 동맹을 유지하고 고구려에 선전포고합니다.',wars:['GOGURYEO'],allies:[['SILLA','BAEKJE','ALLIANCE']]},{label:'대가야 철기 연맹 & 신라 견제전',detail:'대가야와 군사 동맹을 맺고 신라를 공격합니다.',wars:['SILLA'],allies:[['BAEKJE','GAYA','ALLIANCE']],breakAlliance:true}];return[{label:'한성 사수 및 백제 주력 격파전',detail:'신라에 3턴 밀약을 보내고 백제에 역습합니다.',wars:['BAEKJE'],pacts:['SILLA']},{label:'남진 전면전 · 신라',detail:'밀약 없이 신라에 전면전을 선포합니다.',wars:['SILLA']},{label:'남진 전면전 · 양국 모두',detail:'신라와 백제 양국에 동시에 전면전을 선포합니다.',wars:['SILLA','BAEKJE']}]}
function openWarStrategy(){let dialog=document.getElementById('diplomacy-strategy');if(!dialog){dialog=document.createElement('dialog');dialog.id='diplomacy-strategy';document.body.append(dialog)}const plans=strategyPlans();dialog.innerHTML='<h2>출병 및 외교 전략 의제</h2><p>먼저 동맹과 밀약, 전쟁 대상을 선택하십시오. 귀족 회의가 승인하기 전까지 관계는 바뀌지 않습니다.</p><div class="world-brief"><b>전쟁 명분 '+state.warJustification+'/100 · 한강 전운 '+state.worldTension+'/100</b><p>'+worldBriefingText()+'</p></div>'+plans.map((p,i)=>'<button class="strategy-option" data-plan="'+i+'"><b>'+(i+1)+'. '+p.label+'</b><br><small>'+p.detail+'</small></button>').join('')+'<div class="btn-row"><button id="strategy-cancel">돌아가기</button></div>';dialog.querySelectorAll('[data-plan]').forEach(button=>button.onclick=()=>{const plan=plans[Number(button.dataset.plan)];dialog.close();openCouncilDebateV043(plan)});dialog.querySelector('#strategy-cancel').onclick=()=>dialog.close();dialog.showModal()}
function councilSpeech(c){if(['gaya_kim','baekje_hae','baekje_jin','goguryeo_yakbu'].includes(c.id))return state.promisedLandClanId===c.id?'한성 땅을 우리 가문에 약속하신다면 선봉에 서겠소!':'전공과 점령지를 보장하신다면 군사를 내겠소.';if(['park_noble','baekje_sa','goguryeo_go'].includes(c.id))return'명분도 없이 군사를 일으키면 백성이 등을 돌립니다.';return state.warJustification>=70&&state.nationalFood>=1200?'대의와 군량이 갖춰졌으니 찬성하겠습니다.':'명분과 군량부터 갖추십시오. 경솔한 출병은 나라를 위태롭게 합니다.'}
function openCouncilDebateV043(plan){state.pendingWarPlan=plan;let dialog=document.getElementById('council-debate');if(!dialog){dialog=document.createElement('dialog');dialog.id='council-debate';document.body.append(dialog)}const nobles=playerClans().filter(c=>!c.isKing),dissent=nobles.filter(c=>c.loyalty<55),support=nobles.length-dissent.length;dialog.innerHTML='<h2>'+councilName()+' · 출병 어전회의</h2><section class="world-brief"><b>선택 노선: '+plan.label+'</b><p>'+plan.detail+'</p><b>한강 전운 '+state.worldTension+'/100 · 전쟁 명분 '+state.warJustification+'/100</b><p>'+worldBriefingText()+'</p></section><p>찬성 '+support+'/'+nobles.length+' · 반대·보류 '+dissent.length+'</p>'+nobles.map(c=>'<p><b>'+c.name+' ('+c.leader+')</b> — “'+councilSpeech(c)+'”</p>').join('')+'<div class="council-choice-list"><section class="action-with-detail"><button id="council-trade">A · 이권 양보</button><small>왕권 −10 · 대표 가문 사병 +300</small></section><section class="action-with-detail"><button id="council-bribe">B · 국고 회유</button><small>국고 −150금 · 군량 −200 · 대상 충성 +20</small></section><section class="action-with-detail"><button id="council-force" class="btn-danger">C · 왕명으로 강행</button><small>천명·민심 −15 · 모든 귀족 충성 −20 · 내전 위험 증가</small></section><button id="council-cancel">돌아가기</button></div>';const target=dissent[0]||nobles[0];dialog.querySelector('#council-trade').onclick=()=>{if(target){state.royalAuth=Math.max(0,state.royalAuth-10);target.privateArmy+=300;target.loyalty=Math.min(100,target.loyalty+25)}passCouncil(dialog,'정치적 타협으로 출병 의제를 통과시켰습니다.')};dialog.querySelector('#council-bribe').onclick=()=>{if(state.nationalGold<150||state.nationalFood<200){addLog('회유에는 금 150과 군량 200이 필요합니다.');return}state.nationalGold-=150;state.nationalFood-=200;for(const c of dissent)c.loyalty=Math.min(100,c.loyalty+20);if(nobles.filter(c=>c.loyalty>=55).length>nobles.length/2)passCouncil(dialog,'국고 회유로 귀족 과반의 동의를 얻었습니다.');else addLog('회유 후에도 과반에 미달합니다. 추가 협의가 필요합니다.');renderAll()};dialog.querySelector('#council-force').onclick=()=>{state.legitimacy=Math.max(0,state.legitimacy-15);for(const c of nobles)c.loyalty=Math.max(0,c.loyalty-20);passCouncil(dialog,'왕명으로 출병을 강행했습니다. 내전 위기가 커집니다.')};dialog.querySelector('#council-cancel').onclick=()=>{state.pendingWarPlan=null;dialog.close()};dialog.showModal()}
function passCouncil(dialog,message){const plan=state.pendingWarPlan;if(plan){for(const target of plan.wars)setRelation(state,state.playerFaction,target,'WAR');for(const [a,b,status]of plan.allies||[]){setRelation(state,a,b,status);if(status==='ALLIANCE'){const partner=a===state.playerFaction?b:a;for(const target of plan.wars)if(target!==partner)setRelation(state,partner,target,'WAR')}}for(const target of plan.pacts||[])setRelation(state,state.playerFaction,target,'SECRET_PACT',state.turn+3,'3턴 밀약');if(plan.breakAlliance){setRelation(state,'SILLA','BAEKJE','WAR');state.allianceBroken=true;setTrust(Math.min(state.trust,25))}state.warTargets=[...plan.wars];addLog('외교 노선 확정: '+plan.label+'. 전쟁 대상: '+plan.wars.map(f=>FACTIONS[f].name).join(', ')+'.')}state.pendingWarPlan=null;state.warAgendaApproved=true;state.northWarApproved=true;dialog?.close();addLog(message);renderAll()}
function worldBriefingText(){return state.lastWorldBriefing||'한강 유역의 정세를 살피는 중입니다.'}
function metricStatus(metric,value){if(metric==='royalAuth')return value>=60?['충분함(안정)','good']:value>=40?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='nationalFood')return value>=800?['충분함(안정)','good']:value>=300?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='nationalGold')return value>=300?['충분함(안정)','good']:value>=150?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='trust')return value>=60?['충분함(안정)','good']:value>40?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='mandate')return value>=70?['충분함(안정)','good']:value>30?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='warJustification')return value>=60?['충분함(안정)','good']:value>=40?['보통(주의)','warn']:['위험(부족)','bad'];if(metric==='worldTension')return value<40?['충분함(안정)','good']:value<70?['보통(주의)','warn']:['위험(부족)','bad'];return value>=55?['충분함(안정)','good']:value>30?['보통(주의)','warn']:['위험(부족)','bad']}
function monthlyEconomyEstimate(){let food=180,gold=90;for(const tile of Object.values(state.tiles))if(tile.owner===state.playerFaction&&tile.node){if(tile.node.type==='CAPITAL'){food+=120;gold+=80}else if(tile.node.type==='TOWN'){food+=70;gold+=40}else if(tile.node.type==='PORT')gold+=90}const foodUse=playerArmies().filter(a=>a.supplied&&a.troops<a.maxTroops).length*100;return{food,gold,foodNet:food-foodUse,foodUse}}
function metricBriefing(metric){const economy=monthlyEconomyEstimate();if(metric==='iron'||metric==='horses'){const iron=metric==='iron',value=iron?state.iron:state.horses;return{title:iron?'철':'군마',level:value>=80?'충분함(안정)':value>=30?'보통(주의)':'위험(부족)',tone:value>=80?'good':value>=30?'warn':'bad',value:'현재 '+value,delta:'매 턴 보유 생산 거점마다 '+(iron?12:10)+'씩 생산합니다.',impact:iron?'중장보병 편성에 철 40, 기병 편성에 철 50이 필요합니다.':'기병 편성마다 군마 50필이 필요합니다.',action:iron?'웅산 철광·울산 제철항·합천 철성을 점령하십시오.':'춘천 목장을 점령하십시오.'}}if(metric.startsWith('relation:')){const faction=metric.slice(9),relation=getRelation(state,state.playerFaction,faction),status=DIPLOMACY_STATUS[relation.status]||DIPLOMACY_STATUS.NEUTRAL,[level,tone]=relation.status==='WAR'?['교전 중','bad']:relation.status==='ALLIANCE'?['동맹','good']:relation.status==='SECRET_PACT'?['밀약 유지','good']:['경계·대치','warn'];return{title:FACTIONS[faction]?.name+' 외교 관계',level,tone,value:status.label,delta:relation.expiresAt?'밀약 만료까지 '+Math.max(0,relation.expiresAt-state.turn)+'턴 남았습니다.':'이번 턴 관계 만료 없음.',impact:'동맹·밀약·중립국 영토는 진입할 수 없고, WAR 상태인 국가에만 공격과 점령이 허용됩니다.',action:relation.note||'관계는 출병 전략 의제에서 변경합니다.'}}if(metric.startsWith('clan:')){const clan=state.clans[metric.slice(5)];if(!clan)return null;const [level,tone]=metricStatus('clan',clan.loyalty),martial=['gaya_kim','baekje_hae','baekje_jin','goguryeo_yakbu'].includes(clan.id),conservative=['park_noble','baekje_sa','goguryeo_go'].includes(clan.id),promised=state.promisedLandClanId===clan.id?'점령지 분봉 서약이 걸려 있습니다.':state.marriageContracts?.has(clan.id)?'정략혼인 동맹으로 결속되어 있습니다.':martial?'무장파: 점령지 분봉 약속으로 충성 +25, 출병 동의를 얻을 수 있습니다.':conservative?'보수 명문가: 정략혼인(충성 +30) 또는 3턴 조세 감면(충성 +15)으로 포섭할 수 있습니다.':'신중파: 명분 70 및 군량 1,200을 갖추거나 전략 군사권을 위임해 설득할 수 있습니다.';return{title:clan.name,region:clan.region,famousFor:clan.famousFor,lore:clan.lore,level,tone,value:'충성도 '+clan.loyalty+'% · 사병 '+clan.privateArmy.toLocaleString()+'명',delta:'충성도는 매 턴 고정 변동이 없고, 회의 거래·정책·전투 사건에 따라 바뀝니다.',impact:'충성도 55% 이상은 회의 찬성, 31~54%는 보류, 30% 이하는 반란 위험입니다. 사병은 가문 봉토의 독자 군사력입니다.',action:promised}}
 let value=0,title='',delta='',impact='',action='';switch(metric){case'royalAuth':value=state.royalAuth;title='왕권';delta='정기적인 고정 변동은 없습니다. 율령·중앙집권 개혁은 +10, 정략혼인은 -12, 정치적 타협은 -10입니다.';impact='60% 이상이면 율령 반포로 귀족 사병을 흡수할 수 있습니다. 40% 이하는 대귀족 정변 위험 구간입니다.';action='현재 '+value+'% ('+(value>=60?'왕권 우세':value>=40?'균형 상태':'정변 위험')+'). 가문과 혼인할 때 왕권 -12%를 감수합니다.';break;case'nationalFood':value=state.nationalFood;delta='다음 턴 예상: 군량 +'+economy.food+' 생산, 보충 중인 군단 '+economy.foodUse+' 소모 (순증 '+economy.foodNet+').';impact='새 군단 창설에는 300, 병력 보충에는 보충 군단마다 100이 필요합니다.';action='현재 '+value.toLocaleString()+' ('+(value>=800?'충분함':'부족 주의')+' - 신규 군단 약 '+Math.floor(value/300)+'회 소집 가능).';title='군량';break;case'nationalGold':value=state.nationalGold;delta='다음 턴 예상 국고 수입 +'+economy.gold+' (보유 거점 기준).';impact='신규 군단 창설 200금, 어전회의 회유 150금, 전쟁 명분 공작 80금에 사용합니다.';action='현재 '+value.toLocaleString()+' ('+(value>=300?'충분함':'주의')+').';title='국고';break;case'trust':value=state.trust;delta='정기 변동은 없으며 외교 선택과 사건에 따라 바뀝니다.';impact='60 이상이면 견고한 나제동맹이며 엔딩 D 조건에 기여합니다. 40 이하는 동맹 파기·관산성 기습 위험입니다.';action='현재 '+value+'/100 ('+(value>=60?'견고한 동맹':value>40?'흔들리는 동맹':'파기 위험')+').';title='나제동맹 신뢰도';break;case'mandate':value=state.legitimacy;delta='정기 고정 변동은 없으며 왕명 강행·국경 사건·정책으로 변합니다.';impact='70 이상이면 전 군단 사기 회복 +5 보너스가 적용됩니다. 왕명 강행은 -15, 30 이하는 민란 위험입니다.';action='현재 '+value+'/100 ('+(value>=70?'백성의 지지 높음':value>30?'주의':'민란 위험')+').';title='천명·민심';break;case'warJustification':value=state.warJustification;delta='통상 턴에는 변동 없음. 정세 사건·국경 대응·공작으로 증가합니다.';impact='60 이상이어야 출병·외교 전략 의제를 상정할 수 있습니다. 70 이상이면 군량 1,200 이상 보유 시 신중파가 찬성합니다.';action='현재 '+value+'/100. 부족 시 국경 공작(금 80, +25), 옛 강역 선포(민심 -8, +20), 국경 사건 대응을 이용하십시오.';title='전쟁 명분';break;case'worldTension':value=state.worldTension;delta='북방·해상·국경 정세 이벤트가 발생하면 변합니다.';impact='전운이 높을수록 외교 위기와 전쟁 이벤트가 자주 표면화됩니다.';action=state.lastWorldBriefing;title='한강 전운';break;default:return null}const [level,tone]=metricStatus(metric,value);return{title,level,tone,value:metric==='nationalGold'||metric==='nationalFood'?'현재 '+value.toLocaleString():`현재 ${value}/100`,delta,impact,action}}
function renderMetricInspector(metric){const info=metricBriefing(metric),card=$('metric-inspector');if(!info)return;card.hidden=false;const lore=info.lore?`<div class="clan-lore"><b>${UI_LABELS.loreRegion}:</b> ${escapeHtml(info.region)}<br><b>${UI_LABELS.loreFamous}:</b> ${escapeHtml(info.famousFor)}<p><b>${UI_LABELS.loreDisposition}</b><br>${escapeHtml(info.lore)}</p></div>`:'';$('metric-inspector-content').innerHTML=`<div class="section-title">${escapeHtml(info.title)} ${UI_LABELS.metricDetailsHeading}</div>${lore}<div class="metric-status ${info.tone}">${escapeHtml(info.level)}</div><p><b>${escapeHtml(info.value)}</b></p><p><b>${UI_LABELS.metricDeltaHeading}</b><br>${escapeHtml(info.delta)}</p><p><b>${UI_LABELS.metricImpactHeading}</b><br>${escapeHtml(info.impact)}</p><p><b>${UI_LABELS.metricActionHeading}</b><br>${escapeHtml(info.action)}</p>`}
function refreshMetricTooltips(){document.querySelectorAll('[data-metric]').forEach(el=>{const info=metricBriefing(el.dataset.metric);if(info)el.title=info.title+' · '+info.value+' · '+info.level+' — 클릭하여 상세 브리핑'})}
function renderRelations(){const statusBox=$('diplomacy-status');statusBox.innerHTML=statusBox.innerHTML.replace('백제-신라 신뢰 '+state.trust+'/100','<span data-metric="trust" tabindex="0">백제-신라 신뢰 '+state.trust+'/100</span>');const dom=statusBox.querySelector('#metric-domain'),war=statusBox.querySelector('#metric-war-justification'),tension=statusBox.querySelector('#metric-world-tension');if(dom)dom.dataset.metric='domain';if(war)war.dataset.metric='warJustification';if(tension)tension.dataset.metric='worldTension';const box=$('relations-overview');if(!box)return;const others=['SILLA','BAEKJE','GOGURYEO','GAYA'].filter(f=>f!==state.playerFaction);box.innerHTML='<div class="relation-list">'+others.map(f=>{const relation=getRelation(state,state.playerFaction,f),status=DIPLOMACY_STATUS[relation.status]||DIPLOMACY_STATUS.NEUTRAL,expiry=relation.expiresAt?' · '+Math.max(0,relation.expiresAt-state.turn)+'턴 남음':'';return'<button class="relation-chip '+relation.status.toLowerCase()+'" data-metric="relation:'+f+'">'+status.icon+' '+FACTIONS[f].name+' · '+status.label+expiry+'</button>'}).join('')+'</div>'}
function runWorldTensionTurn(){if(state.worldEventTurn===state.turn)return;state.worldEventTurn=state.turn;if(state.turn%3===0){const weak=playerArmies().filter(a=>!a.supplied).length,disloyal=playerClans().filter(c=>!c.isKing&&c.loyalty<50).sort((a,b)=>a.loyalty-b.loyalty)[0],enemyTiles=Object.values(state.tiles).filter(t=>t.owner!==state.playerFaction).length;const title=weak?$('dynamic-title-supply').textContent:disloyal?$('dynamic-title-noble').textContent:$('dynamic-title-front').textContent;const summary=weak?$('dynamic-summary-supply').textContent.replace('{count}',weak):disloyal?$('dynamic-summary-noble').textContent.replace('{name}',disloyal.name).replace('{loyalty}',disloyal.loyalty):$('dynamic-summary-front').textContent.replace('{turn}',state.turn).replace('{tiles}',enemyTiles);let dialog=document.getElementById('dynamic-incident');if(!dialog){dialog=document.createElement('dialog');dialog.id='dynamic-incident';document.body.append(dialog)}dialog.innerHTML='<h2>'+title+'</h2><p>'+summary+'</p><div class="btn-row"><button id="dynamic-reinforce">'+$('dynamic-label-reinforce').textContent+'</button><button id="dynamic-claim">'+$('dynamic-label-claim').textContent+'</button></div>';dialog.querySelector('#dynamic-reinforce').onclick=()=>{if(state.nationalGold<100||state.nationalFood<200){addLog('증원에 필요한 국고 또는 군량이 부족합니다.');dialog.close();return}state.nationalGold-=100;state.nationalFood-=200;const army=spawnHouseArmy(activeClan(),600,'수도 구원군');dialog.close();addLog(`정세 사건: ${army?.name||'구원군'} 600명이 지도에 도착했습니다.`);renderAll()};dialog.querySelector('#dynamic-claim').onclick=()=>{state.warJustification=Math.min(100,state.warJustification+20);state.legitimacy=Math.max(0,state.legitimacy-2);dialog.close();addLog('정세 사건: 왕실 교서로 전쟁 명분이 20 상승했습니다.');renderAll()};dialog.showModal();return}const mod=state.turn%4;if(mod===2||mod===0){const event=mod===2?WORLD_TENSION_EVENTS.northern:WORLD_TENSION_EVENTS.maritime;state.warJustification=Math.min(100,state.warJustification+event.justification);state.worldTension=Math.min(100,state.worldTension+event.tension);state.lastWorldBriefing=`${mod===2?'🐎':'⛵'} [${event.title}] ${event.message} (전쟁 명분 +${event.justification})`;addLog(state.lastWorldBriefing);renderAll();return}const event=WORLD_TENSION_EVENTS.border;state.worldTension=Math.min(100,state.worldTension+event.tension);state.lastWorldBriefing=`🔥 [${event.title}] ${event.message}`;let dialog=document.getElementById('border-incident');if(!dialog){dialog=document.createElement('dialog');dialog.id='border-incident';document.body.append(dialog)}dialog.innerHTML=`<h2>${event.title}</h2><p>${event.message}</p><div class="btn-row"><button id="border-condemn">🅰️ 사신을 보내 규탄하고 명분을 쌓는다 (명분 +25)</button><button id="border-endure">🅱️ 참는다 (민심 -5, 동맹 신뢰 +10)</button></div>`;dialog.querySelector('#border-condemn').onclick=()=>{state.warJustification=Math.min(100,state.warJustification+event.justification);state.worldTension=Math.min(100,state.worldTension+5);state.lastWorldBriefing=`국경 약탈을 조정에 고발하여 정당한 대응 명분을 얻었습니다 (+${event.justification}).`;dialog.close();addLog(state.lastWorldBriefing);renderAll()};dialog.querySelector('#border-endure').onclick=()=>{state.legitimacy=Math.max(0,state.legitimacy-5);state.trust=Math.min(100,state.trust+10);state.worldTension=Math.max(0,state.worldTension-5);state.lastWorldBriefing='국경 충돌을 감내하고 동맹의 신뢰를 지켰습니다.';dialog.close();addLog(state.lastWorldBriefing);renderAll()};dialog.showModal()}
function proposeCentralize(){const clan=activeClan(),king=playerClans().find(c=>c.isKing);if(!clan?.isKing){if(state.playerFaction==='GOGURYEO'){state.defenseBonus=(state.defenseBonus||1)+.15;addLog('5부 귀족 통제와 태학 정비를 단행해 산성 방어 태세를 강화했습니다.')}else if(state.playerFaction==='BAEKJE'){state.damroInfluence=(state.damroInfluence||0)+1;addLog('22담로 왕족을 파견해 지방 통치와 대성팔족 견제를 강화했습니다.');markStateAction('army-raised')}renderAll();return}if(state.nationalGold<150)return addLog('개혁에는 국고 150이 필요합니다.');state.nationalGold-=150;state.royalAuth=Math.min(100,state.royalAuth+10);for(const noble of playerClans().filter(c=>!c.isKing)){const absorbed=Math.min(noble.privateArmy,300);noble.privateArmy-=absorbed;noble.loyalty=Math.max(0,noble.loyalty-12);let royalArmy=state.armies.find(a=>a.owner===state.playerFaction&&a.clanId===king.id);if(!royalArmy){const [q,r]=FACTION_START[state.playerFaction].tile.split(',').map(Number);royalArmy={id:`a_${state.playerFaction.toLowerCase()}_royal_${state.turn}`,name:`${FACTIONS[state.playerFaction].name} 왕실군`,owner:state.playerFaction,clanId:king.id,q,r,troops:0,maxTroops:0,morale:90,supplied:true,ap:2};state.armies.push(royalArmy)}royalArmy.troops+=absorbed;royalArmy.maxTroops+=absorbed}addLog(`${councilName()} 개혁: 왕권 +10, 대귀족 사병을 왕실군에 흡수했습니다.`);if(state.playerFaction==='SILLA')markStateAction('silla-policy');if(state.playerFaction==='GOGURYEO')markStateAction('goguryeo-policy');checkNobleRevoltRisk();renderAll()}
function rewardClan(id){const clan=state.clans[id];if(!activeClan()?.isKing||!clan||clan.faction!==state.playerFaction||clan.isKing||state.nationalGold<100)return addLog('왕실 시작 가문과 국고 100금을 확인하세요.');state.nationalGold-=100;clan.gold+=100;clan.loyalty=Math.min(100,clan.loyalty+18);addLog(`${clan.name}에 금 100을 하사했습니다. 충성도 ${clan.loyalty}%.`);if(state.playerFaction==='SILLA')markStateAction('silla-policy');checkNobleRevoltRisk();renderAll()}
function recruitPrivateTroops(){const clan=activeClan();if(!clan||clan.gold<100)return addLog('시작 가문 금고에 금 100이 필요합니다.');clan.gold-=100;clan.privateArmy+=400;addLog(`${clan.name}이 영지 자금으로 사병 400명을 모집했습니다.`);renderAll()}
function acceptRoyalOrder(){if(activeClan()?.isKing)return;state.coupMandate=false;state.royalAuth=Math.min(100,state.royalAuth+5);for(const c of playerClans().filter(c=>c.isKing))c.loyalty=Math.min(100,c.loyalty+5);addLog('왕실의 명령을 수용해 신임을 얻었습니다.');renderAll()}
function rejectRoyalOrder(){if(activeClan()?.isKing)return addLog('왕실 시작 가문은 왕실 명령 거부권을 행사할 수 없습니다.');state.coupMandate=true;state.royalAuth=Math.max(0,state.royalAuth-12);for(const c of playerClans().filter(c=>c.isKing))c.loyalty=Math.max(0,c.loyalty-8);addLog('왕실 명령을 거부했습니다. 찬탈 명분을 확보했으며 왕권이 하락했습니다.');renderAll()}
function launchCoup(){const clan=activeClan(),king=playerClans().find(c=>c.isKing);if(!hasCoupConditions())return addLog('정변 조건 미충족: 명분 확보 후 왕권 40 이하 또는 왕실군보다 사병 우위가 필요합니다.');if(!clan||!king)return;king.isKing=false;clan.isKing=true;state.coupMandate=false;state.royalAuth=55;addLog(`${clan.leader}이 정변을 일으켜 왕위를 찬탈했습니다.`);renderAll()}
function checkNobleRevoltRisk(){if(!state.started||!activeClan()?.isKing||state.revoltPending)return;const rebel=playerClans().find(c=>!c.isKing&&c.loyalty<=30);if(!rebel)return;state.revoltPending=true;enqueueStoryEvent('revolt',rebel.id)}
function renderRevoltEvent(clanId){const clan=state.clans[clanId];if(!clan){state.revoltPending=false;state.eventOpen=false;return}$('cutscene-kicker').textContent='정변 위기 · 귀족 반란';$('cutscene-title').textContent=`${clan.name}의 봉기`;const line=document.createElement('div');line.className='dialogue-line';line.innerHTML=`<span class="speaker">${escapeHtml(clan.leader)}</span><span class="mood">${escapeHtml(displayEmotion('angry'))}</span><br>충성도 ${clan.loyalty}%까지 떨어진 귀족이 사병을 모아 왕실에 반기를 들었습니다.`;$('cutscene-lines').replaceChildren(line);const options=[['회유한다',()=>{state.nationalGold=Math.max(0,state.nationalGold-150);clan.loyalty=50;clan.privateArmy=Math.max(200,clan.privateArmy-200);addLog(`${clan.name}과 타협해 봉기를 진정시켰습니다.`)}],['왕실군으로 진압한다',()=>{const army=state.armies.find(a=>a.owner===state.playerFaction&&a.clanId===playerClans().find(c=>c.isKing)?.id);if(army){army.troops+=clan.privateArmy;army.maxTroops+=clan.privateArmy}clan.privateArmy=0;clan.loyalty=45;addLog(`${clan.name}의 사병을 해산하고 왕실군에 편입했습니다.`)}]];$('cutscene-choices').replaceChildren(...options.map(([label,action],i)=>{const button=document.createElement('button');button.textContent=`${i?'🅱️':'🅰️'} · ${label}`;const note=document.createElement('small');note.className='choice-preview';note.textContent=i?'결과: 반란군을 진압하고 사병을 왕실군에 편입합니다.':'결과: 국고 150금 지출, 충성 회복과 사병 일부 해산.';button.append(note);button.onclick=()=>{action();state.revoltPending=false;state.eventOpen=false;$('cutscene-modal').close();renderAll();queueMicrotask(pumpStoryQueue)};return button}));$('btn-cutscene-continue').style.display='none';$('btn-cutscene-close').style.display='none';$('cutscene-modal').showModal()}
function raiseNewArmyLegacy(q,r,type=state.selectedUnitType||'INFANTRY'){const clan=activeClan(),unit=UNIT_TYPES[type]||UNIT_TYPES.INFANTRY;if(state.tiles[tileKey(q,r)]?.owner!==state.playerFaction)return addLog('자국 소유 거점에서만 군단을 창설할 수 있습니다.');if(state.nationalGold<unit.gold||state.nationalFood<unit.food||state.iron<(unit.iron||0)||state.horses<(unit.horse||0))return addLog('선택한 병종을 편성하기 위한 국고·군량·철·말이 부족합니다.');state.nationalGold-=unit.gold;state.nationalFood-=unit.food;state.iron-=unit.iron||0;state.horses-=unit.horse||0;state.armySeq++;const commander=state.generals.find(g=>g.faction===state.playerFaction);state.armies.push({id:`a_${state.playerFaction.toLowerCase()}_${state.armySeq}`,name:`${clan.leader} ${unit.label}군`,owner:state.playerFaction,clanId:clan.id,commanderId:commander?.id||null,unitType:type,q,r,troops:1800,maxTroops:2000,morale:100,supplied:true,ap:unit.ap});state.selectedArmyId=state.armies.at(-1).id;addLog(`${state.armies.at(-1).name}을 (${q},${r})에 창설했습니다.`);markStateAction('army-raised');renderAll()}
function chooseArmyType(q,r){let dialog=document.getElementById('recruit-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='recruit-dialog';document.body.append(dialog)}dialog.innerHTML=`<h2>신규 군단 병종 선택</h2><p>편성할 병종과 지불할 자원을 확인하십시오.</p><div class="unit-choice-grid">${Object.entries(UNIT_TYPES).map(([id,u])=>`<button data-unit="${id}"><b>${u.label}</b><small>금 ${u.gold} · 군량 ${u.food} · 철 ${u.iron||0} · 말 ${u.horse||0} · AP ${u.ap}</small></button>`).join('')}</div><button data-close>돌아가기</button>`;dialog.querySelectorAll('[data-unit]').forEach(button=>button.onclick=()=>{raiseNewArmy(q,r,button.dataset.unit);dialog.close()});dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.showModal()}
function mergeArmiesOnTileLegacy(q,r){const stack=state.armies.filter(a=>a.q===q&&a.r===r&&a.owner===state.playerFaction);if(stack.length<2)return;const main=stack[0];for(const army of stack.slice(1)){main.troops+=army.troops;main.maxTroops+=army.maxTroops;main.ap=Math.min(main.ap,army.ap)}const remove=new Set(stack.slice(1).map(a=>a.id));state.armies=state.armies.filter(a=>!remove.has(a.id));state.selectedArmyId=main.id;addLog(`${stack.length}개 군단을 ${main.name}으로 병합했습니다.`);renderAll()}
function splitArmyByIdLegacy(id){const army=state.armies.find(item=>item.id===id&&item.owner===state.playerFaction);if(!army||army.troops<1000){addLog(UI_LABELS.splitUnavailable);return}const half=Math.floor(army.troops/2);army.troops-=half;army.maxTroops=Math.max(army.troops,Math.floor(army.maxTroops/2));state.armySeq++;const detachment={...army,id:`${army.id}_split_${state.armySeq}`,name:`${army.name} · ${state.armySeq} 분견대`,troops:half,maxTroops:Math.max(half,Math.ceil(army.maxTroops)),ap:army.ap};state.armies.push(detachment);state.selectedArmyId=detachment.id;addLog(`${army.name}에서 ${half.toLocaleString()}명을 분리해 새 군단을 편성했습니다.`);renderAll()}
function drawMoveOverlay(){const army=state.armies.find(a=>a.id===state.movingArmyId);if(!army)return;for(const tile of Object.values(state.tiles)){if(getDistance(army.q,army.r,tile.q,tile.r)!==1)continue;const{x,y}=hexToPixel(tile.q,tile.r),danger=isBlockedByEnemyFortZOC(state,tile,army.owner);drawHex(x,y,HEX_SIZE-2,'#00000000',danger?'#f97316':'#3fb950',4);if(danger){ctx.textAlign='center';ctx.fillStyle='#fb923c';ctx.font='bold 10px sans-serif';ctx.fillText('⚠️산성위협(사기-15·보급차단)',x,y+44)}}}
function startMoveArmy(id){const army=state.armies.find(a=>a.id===id);if(!army||army.owner!==state.playerFaction)return;if(army.ap<=0)return addLog('이 군단은 이번 달 행군력을 모두 사용했습니다.');state.movingArmyId=id;renderAll();drawMoveOverlay()}

function applyZocPenalty(army,tile){if(!isBlockedByEnemyFortZOC(state,tile,army.owner))return;army.morale=Math.max(0,army.morale-15);army.ap=0;army.supplied=false;army.zocSupplyCut=true;tile[`suppliedFor${army.owner}`]=false;addLog(`⚠️ ${army.name}이 산성 ZOC로 진입했습니다. 사기 -15, AP 소진, 보급 단절.`)}
function addBattleLog(attacker,defender,tile,result){addLog(`전투(${tile.node?.name||'야전'}): ${attacker.name} 손실 ${result.atkLoss.toLocaleString()} / ${defender.name} 손실 ${result.defLoss.toLocaleString()}${result.captured?' · 거점 함락':''}`)}
function openBattle(attacker,defender,tile,isAI=false){$('battle-modal').style.display='';if(!attacker||!defender||attacker.troops<=50||defender.troops<=50){const old=tile?.owner;state.armies=state.armies.filter(a=>a.troops>50);if(attacker&&defender&&tile&&attacker.troops>50&&defender.troops<=50&&!state.armies.some(a=>a.q===tile.q&&a.r===tile.r&&a.owner!==attacker.owner)){attacker.q=tile.q;attacker.r=tile.r;tile.owner=attacker.owner;onTileCaptured(old,attacker.owner,tile,attacker);addLog(`${attacker.name} 무방비 타일을 점령했습니다.`)}state.movingArmyId=null;renderAll();return}const hasPlayer=attacker.owner===state.playerFaction||defender.owner===state.playerFaction;if(isAI&&!hasPlayer){const result=resolveBattle(state,attacker,defender,tile,'charge','formation',true);if(result.captured)applyZocPenalty(attacker,tile);addBattleLog(attacker,defender,tile,result);if(result.captured)onTileCaptured(result.previousOwner,attacker.owner,tile,attacker);renderAll();return}const pending={attackerId:attacker.id,defenderId:defender.id,tileKey:tileKey(tile.q,tile.r),isAI,playerSide:attacker.owner===state.playerFaction?'attacker':'defender'};if(!state.pendingBattles.some(p=>p.attackerId===pending.attackerId&&p.defenderId===pending.defenderId&&p.tileKey===pending.tileKey))state.pendingBattles.push(pending);if($('battle-modal').open)return;state.movingArmyId=null;const own=attacker.owner===state.playerFaction?attacker:defender;const dialog=$('battle-modal');$('battle-title').textContent=`전술 교전 · ${tile.node?.name||`(${tile.q},${tile.r})`}`;$('battle-summary').textContent=`${attacker.name} (${attacker.troops.toLocaleString()}명) vs ${defender.name} (${defender.troops.toLocaleString()}명)`;$('attacker-label').textContent=`내 전술 · ${own.name}`;$('defender-label').textContent=`적 전술 · ${own===attacker?defender.name:attacker.name}`;const box=document.querySelector('.tactic-options[data-side="player"]');box.replaceChildren();for(const [i,tactic]of (FACTION_TACTICS[own.owner]||FACTION_TACTICS.SILLA).entries()){const label=document.createElement('label');label.className='tactic-choice';label.innerHTML=`<input type="radio" name="player-tactic" value="${tactic.id}" ${i===0?'checked':''}><span>${tactic.name}</span>`;box.append(label)}dialog.showModal()}
function resolvePendingBattle(){const pending=state.pendingBattles.shift();if(!pending)return;const attacker=state.armies.find(a=>a.id===pending.attackerId),defender=state.armies.find(a=>a.id===pending.defenderId),tile=state.tiles[pending.tileKey];if(!attacker||!defender||!tile||attacker.troops<=50||defender.troops<=50){const old=tile?.owner;state.armies=state.armies.filter(a=>a.troops>50);if(attacker&&defender&&tile&&attacker.troops>50&&defender.troops<=50&&!state.armies.some(a=>a.q===tile.q&&a.r===tile.r&&a.owner!==attacker.owner)){attacker.q=tile.q;attacker.r=tile.r;tile.owner=attacker.owner;onTileCaptured(old,attacker.owner,tile,attacker)}state.pendingBattles=[];state.movingArmyId=null;$('battle-modal').close();renderAll();return}const own=pending.playerSide==='attacker'?attacker:defender,enemy=own===attacker?defender:attacker,choice=document.querySelector('input[name="player-tactic"]:checked')?.value||'charge',enemyCards=FACTION_TACTICS[enemy.owner]||FACTION_TACTICS.SILLA,enemyCard=tile.node?.type==='FORT'?enemyCards.find(c=>c.type==='formation'):enemyCards[(enemy.troops+state.turn)%enemyCards.length],atk=own===attacker?choice:enemyCard.id,def=own===defender?choice:enemyCard.id,result=resolveBattle(state,attacker,defender,tile,atk,def,false),ownCard=(FACTION_TACTICS[own.owner]||FACTION_TACTICS.SILLA).find(c=>c.id===choice);if(result.captured)applyZocPenalty(attacker,tile);addBattleLog(attacker,defender,tile,result);addLog(`🗣️ ${own.name}: "진격하라!" · ${enemy.name}: "진형을 지켜라!" · 적 전술 공개: ${enemyCard.name} · ${result.advantage==='attacker'?'공격 우세 ×1.3':result.advantage==='defender'?'방어 우세 ×1.3':'호각 ×1.0'} · 아군 카드 ${ownCard?.name}`);if(result.captured)onTileCaptured(result.previousOwner,attacker.owner,tile,attacker);onBattleResolved(attacker,defender,tile,true);$('battle-modal').close();renderAll()}
function relationMessage(faction){const relation=getRelation(state,state.playerFaction,faction),name=FACTIONS[faction]?.name||faction,label=DIPLOMACY_STATUS[relation.status]?.label||'대치';return `🕊️ 현재 ${name}와는 [${label}] 상태입니다. 침공하려면 조정 회의에서 해당 국가에 대한 전쟁 의제를 통과시키거나 동맹을 파기해야 합니다.`}
function tryMoveOrAttack(tile){const army=state.armies.find(a=>a.id===state.movingArmyId);if(!army)return;if(getDistance(army.q,army.r,tile.q,tile.r)!==1){addLog('인접한 타일로만 이동할 수 있습니다.');state.movingArmyId=null;renderAll();return}if(tile.owner!==army.owner&&getRelation(state,army.owner,tile.owner).status!=='WAR'){addLog(relationMessage(tile.owner));state.movingArmyId=null;renderAll();return}const enemies=state.armies.filter(a=>a.q===tile.q&&a.r===tile.r&&a.owner!==army.owner);const hostile=enemies.filter(a=>getRelation(state,army.owner,a.owner).status==='WAR');if(hostile.length){openBattle(army,hostile.sort((a,b)=>a.troops-b.troops)[0],tile,false);return}if(enemies.length){addLog(relationMessage(enemies[0].owner));state.movingArmyId=null;renderAll();return}const zocFort=isBlockedByEnemyFortZOC(state,tile,army.owner),previousOwner=tile.owner;army.q=tile.q;army.r=tile.r;army.ap=zocFort?0:army.ap-1;army.zocSupplyCut=zocFort;tile.owner=army.owner;if(zocFort){army.morale=Math.max(0,army.morale-15);army.supplied=false;tile[`suppliedFor${army.owner}`]=false;addLog(`⚠️ ${army.name}이 적 산성 ZOC를 강행 돌파했습니다. 사기 -15, AP 소진, 보급 단절!`)}else addLog(`${army.name}이 (${tile.q},${tile.r})로 이동했습니다.`);if(previousOwner!==army.owner)onTileCaptured(previousOwner,army.owner,tile,army);state.movingArmyId=null;state.selectedTileKey=tileKey(tile.q,tile.r);updateSupplyLines(state);if(zocFort){army.supplied=false;tile[`suppliedFor${army.owner}`]=false}renderAll()}

function advanceDiplomacyTurn(){for(const relation of Object.values(state.relations)){if(relation.status==='SECRET_PACT'&&relation.expiresAt!==null&&state.turn>=relation.expiresAt){relation.status='NEUTRAL';relation.expiresAt=null;relation.note='';addLog('은밀한 밀약 기간이 끝나 양국 관계가 다시 경계·대치로 돌아섰습니다.')}}}
function applyPeasantUnrest(){if(state.legitimacy>30||state.lastPeasantRevoltTurn===state.turn)return;state.lastPeasantRevoltTurn=state.turn;state.nationalGold=Math.max(0,state.nationalGold-50);state.nationalFood=Math.max(0,state.nationalFood-80);for(const army of playerArmies())army.morale=Math.max(0,army.morale-5);addLog('🔥 천명·민심이 30 이하로 무너져 민란이 일어났습니다. 국고 -50, 군량 -80, 전 군단 사기 -5.')}
function nextTurn(){if(!state.started)return;state.turn++;state.month++;if(state.month>12){state.month=1;state.year++}let foodGain=180,goldGain=90,ironGain=0,horseGain=0;for(const tile of Object.values(state.tiles))if(tile.owner===state.playerFaction){const output=tileProduction(tile);foodGain+=output.food;goldGain+=output.gold;ironGain+=output.iron;horseGain+=output.horses}state.nationalFood+=foodGain;state.nationalGold+=goldGain;state.iron+=ironGain;state.horses+=horseGain;updateSupplyLines(state);const house=activeClan();if(house){house.gold+=(house.manorLevel||0)*60;house.privateArmy+=(house.manorLevel||0)*150;for(const c of playerClans())if(c.loyaltyDecayTurns>0){c.loyalty=Math.max(0,c.loyalty-5);c.loyaltyDecayTurns--}}for(const army of playerArmies())army.ap=UNIT_TYPES[army.unitType]?.ap||2;state.armies=state.armies.filter(a=>a.troops>50);for(const enemy of state.armies.filter(a=>a.owner!==state.playerFaction))enemy.ap=2;advanceDiplomacyTurn();applyPeasantUnrest();checkNobleRevoltRisk();runEnemyTurns(state,{log:addLog,queueBattle:(a,d,t,isAI)=>openBattle(a,d,t,isAI),onTileCaptured});updateSupplyLines(state);if(state.triggers.hanseongBattleTurn!==null&&state.turn>=state.triggers.hanseongBattleTurn){state.triggers.hanseongBattleTurn=null;if(!state.quests.completed.has('MQ-02'))if(state.playerFaction==='SILLA'||state.playerFaction==='BAEKJE')showCutscene(state.playerFaction==='BAEKJE'?'CS-02-B':'CS-02-S')}checkActionTriggers('turn');addLog(`${state.year}년 ${state.month}월 · 군량 +${foodGain}, 금 +${goldGain}.`);renderAll()}

const captureCoreV051=onTileCaptured;onTileCaptured=function(previousOwner,newOwner,tile,army){if(previousOwner!==newOwner){tile.assimilationTurns=0;tile.isCore=false;tile.resistance=45;tile.compliance=10;tile.occupationPolicy='BALANCED';tile.occupationOriginOwner=previousOwner;tile.rebellionTriggered=false;tile.buildings??={};tile.yields??={gold:0,food:0,iron:0,horses:0}}return captureCoreV051(previousOwner,newOwner,tile,army)};
const battleOpenCoreV051=openBattle;openBattle=function(attacker,defender,tile,isAI=false){battleOpenCoreV051(attacker,defender,tile,isAI);if($('battle-modal').open&&attacker&&defender)$('battle-summary').textContent=`${attacker.name} (${attacker.troops.toLocaleString()}명 · ${compositionText(attacker)}) vs ${defender.name} (${defender.troops.toLocaleString()}명 · ${compositionText(defender)})`};
const turnCoreV051=nextTurn;nextTurn=function(){const before=new Map(state.armies.map(army=>[army.id,army.troops]));turnCoreV051();const supreme=state.generals.find(g=>g.id===state.supremeCommanderId),foodRefund=Math.floor((supreme?.intellect||0)/4),moraleGain=supreme?Math.floor(supreme.leadership/25):0;for(const army of playerArmies()){const previous=before.get(army.id)||army.troops;if(army.troops>previous)adjustComposition(army,{[army.unitType||'INFANTRY']:army.troops-previous});else if(army.troops<previous)adjustComposition(army,{[army.unitType||'INFANTRY']:army.troops-previous});army.morale=Math.min(100,army.morale+moraleGain);if(army.troops>previous)state.nationalFood+=foodRefund}if(supreme)addLog(`국군 총사령관 ${supreme.name}의 통솔로 전군 사기 +${moraleGain}, 보급 소모가 줄었습니다.`);renderAll()};
const chronicleCoreV051=chronicle;chronicle=function(questId,choice,result){const choices={HIGH:'경계를 문서로 명확히 규정함',LOW:'구두 맹약으로 실리를 택함',NONE:'맹약의 해석을 유보함',DEFENSE:'청야전술로 산성망에 의지해 지구전을 편다',OFFENSE:'한강 이남으로 선제 도하한다',PACT:'신라에 비밀 밀사를 보내 동맹을 흔든다',FULL:'한강 하류를 전부 취한다',PARTIAL:'약속한 몫만 취한다',DELEGATE:'현장 장수에게 결정을 맡긴다',IGNORE:'침공을 감내하고 기다린다',PREEMPT:'선제 대응한다',CAPTURED:'성왕을 사로잡는다',DIES:'성왕이 전사한다',SPARED:'성왕을 살려 보낸다'};let text=String(result||'');if(text.startsWith('TREATY_clarity='))text=`한강 맹약 ${choice==='HIGH'?'명문화':choice==='LOW'?'구두 합의':'해석 유보'}, 나제동맹 신뢰도 ${state.trust}`;else if(text.includes('trust '))text=`나제동맹 신뢰도 ${state.trust}`;else if(text.startsWith('{')){try{const reward=JSON.parse(text),labels={gold:'국고',troops:'병력',legitimacy:'천명·민심',trust:'동맹 신뢰',gayaBaekje:'대가야의 백제 호감',gayaSilla:'대가야의 신라 호감',pact:'고구려 밀약'};text=Object.entries(reward).map(([key,value])=>`${labels[key]||'보상'} ${typeof value==='boolean'?(value?'성립':'불성립'):value}`).join(' · ')}catch{}}chronicleCoreV051(questId,choices[choice]||choice,text)};
function renderQuestCardsLegacyA(quests){let futureShown=false;return quests.map((quest,index)=>{const completed=state.quests.completed.has(quest.id),active=index===state.quests.mainIndex;if(!completed&&!active){if(futureShown)return'';futureShown=true;return`<div class="quest-card quest-blind"><b>${UI_LABELS.questUnknown}</b><p>${UI_LABELS.questUnknownDescription}</p></div>`}const history=(state.quests.history||[]).filter(entry=>entry.questId===quest.id),record=history.map(entry=>`<div class="quest-chronicle">✒️ 나의 역사 기록 · 제${entry.turn}턴: ${escapeHtml(entry.choice)} 선택 → ${escapeHtml(entry.result)}</div>`).join('');return`<div class="quest-card ${active?'active':''}"><b>${escapeHtml(quest.title)}</b><span class="quest-state">${completed?UI_LABELS.questDone:UI_LABELS.questActive}</span><p>${escapeHtml(quest.description)}</p>${active?`<p class="quest-objective">${questObjective(quest.id)}</p>`:''}${record}</div>`}).join('')}
