function renderActionDetails(){const details={house:['본가 사병 −800명 · 수도에 직할 군단 800명 출진','가문 자금 −150금 · 매 턴 가문 수입 +60금·사병 +150명 · 왕권 +5','가문 자금 −100금 · 밀정 약점 +1','가문 자금 −120금 · 모든 가문 충성 +10 · 천명·민심 +8 · 무관 등용 기회'],noble:['가문 자금 −100금 · 충성 +15 (관료파는 효과 감소)','비용 없음 · 충성 +25 · 지원군 1,000명 출현 · 점령지 분봉 약속','충성 +30 · 영구 우호 · 왕권 −8','약점 1 소모 · 회의 찬성 강제 · 왕권 +5 · 이후 충성 하락','성공 시 가문 자금·사병 절반 몰수, 왕권 +15 · 실패 시 반란군 출현']};for(const[selector,key]of[['#house-actions','house'],['#clan-actions','noble']]){const root=$(selector);if(!root)continue;[...root.querySelectorAll(':scope > button')].forEach((button,index)=>{if(button.parentElement.classList.contains('action-with-detail'))return;const wrapper=document.createElement('div');wrapper.className='action-with-detail';const note=document.createElement('small');note.textContent=details[key][index]||'';button.removeAttribute('data-tooltip');button.before(wrapper);wrapper.append(button,note)})}}
