function supremeCommanderCandidatePool(){const duties=new Map();for(const army of state.armies){if(army.commanderId)duties.set(army.commanderId,`${army.name} · ${factionOffices(army.owner).commander}`);if(army.subCommanderId)duties.set(army.subCommanderId,`${army.name} · ${factionOffices(army.owner).vanguard}`)}return state.generals.filter(g=>g.faction===state.playerFaction).map(g=>({...g,assignedDuty:duties.get(g.id)||null})).sort((a,b)=>(b.leadership+b.intellect)-(a.leadership+a.intellect))}
