function renderSupremeCommander(){const box=$('supreme-commander-office');if(!box)return;const office=factionOffices(),incumbent=state.generals.find(g=>g.id===state.supremeCommanderId&&g.faction===state.playerFaction);$('supreme-commander-title').textContent=office.supreme;box.replaceChildren();const card=document.createElement('article');card.className='office-card';card.innerHTML=`<b>${escapeHtml(office.supreme)}</b><div>담당: 전군 지휘와 전투력 보정</div><div>현 임명자: ${escapeHtml(incumbent?.name||'공석')}</div><div>실제 효과: ${escapeHtml(commanderEffectText(incumbent))}</div><button type="button">${incumbent?'임명·교체':'임명'}</button>`;card.querySelector('button').onclick=()=>openCommanderCandidates('manual');box.append(card);const auto=$('btn-auto-appoint'),recommend=$('btn-recommend-commander');if(auto)auto.disabled=Boolean(incumbent);if(recommend)recommend.disabled=false}
function openCommanderCandidates(mode='manual'){const dialog=$('appointment-modal'),list=$('appointment-candidates'),pool=supremeCommanderCandidatePool(),current=state.generals.find(g=>g.id===state.supremeCommanderId),eligible=pool.filter(g=>!g.assignedDuty&&g.id!==state.supremeCommanderId),best=eligible[0];$('appointment-title').textContent=mode==='auto'?'빈 관직 추천 임명':'총사령관 임명 후보';$('appointment-office-effect').textContent=`${factionOffices().supreme} · ${commanderEffectText(current)}. 통솔+지략이 높은 후보를 우선 추천하며, 다른 군단 임무를 맡은 장수는 이동시키지 않습니다.`;list.replaceChildren();if(mode==='auto'&&current){const p=document.createElement('p');p.className='appointment-empty';p.textContent=`현재 ${current.name}이 임명되어 있어 자동 임명으로 교체하지 않습니다.`;list.append(p)}else if(mode==='auto'&&!best){const p=document.createElement('p');p.className='appointment-empty';p.textContent='임명 가능한 대기 장수가 없습니다. 기존 군단 임무는 유지됩니다.';list.append(p)}else{for(const g of pool){const allowed=!g.assignedDuty&&g.id!==state.supremeCommanderId,reason=g.id===best?.id?'추천: 임명 가능한 후보 중 통솔+지략이 가장 높습니다.':g.assignedDuty?`임명 불가: 현재 ${g.assignedDuty} 임무를 맡고 있습니다.`:g.id===state.supremeCommanderId?'현재 총사령관입니다.':'';const row=document.createElement('div');row.className='appointment-candidate-card';const button=document.createElement('button');button.type='button';button.className='appointment-candidate';button.disabled=!allowed;button.innerHTML=`<b>${g.id===best?.id?'★ 추천 · ':''}${escapeHtml(g.name)}</b><small>통솔 ${g.leadership} · 무력 ${g.martial} · 지략 ${g.intellect} · ${escapeHtml(g.traits?.join('·')||'특성 없음')}</small><small>현재 임무: ${escapeHtml(g.assignedDuty||(g.id===state.supremeCommanderId?'총사령관':'대기'))}</small><span>${escapeHtml(reason||'임명 가능')}</span>`;button.onclick=()=>{if(!allowed)return;if(mode!=='manual'||current){const prompt=mode==='auto'?`${g.name}을(를) 추천 총사령관으로 임명합니다. 적용하시겠습니까?`:current?`${current.name}을(를) 총사령관에서 교체하고 ${g.name}을(를) 임명하시겠습니까?`:`추천 후보 ${g.name}을(를) 총사령관으로 임명하시겠습니까?`;if(!window.confirm(prompt))return}assignSupremeCommander(g.id);dialog.close()};row.append(button);list.append(row)}}$('btn-appointment-cancel').onclick=()=>dialog.close();dialog.showModal()}
