const nextTurnV052=nextTurn;nextTurn=function(){const previousGold=state.nationalGold;nextTurnV052();for(const clan of playerClans())if(!clan.isKing&&(clan.fiefCount||0)>0){clan.gold+=60*clan.fiefCount;clan.privateArmy+=150*clan.fiefCount}for(const tile of Object.values(state.tiles)){const ruler=state.clans[tile.rulerClanId];if(tile.owner===state.playerFaction&&tile.node&&ruler&&!ruler.isKing){const incomeBase=tile.node.type==='CAPITAL'?80:tile.node.type==='TOWN'?40:tile.node.type==='PORT'?90:0,share=Math.floor(incomeBase*(tile.rulerTaxShare??.5));state.nationalGold=Math.max(0,state.nationalGold-share);ruler.gold+=share}}for(const army of playerArmies()){army.training=Math.min(100,(army.training||20)+3);if(army.mustering&&army.troops<army.maxTroops&&army.supplied&&(army.supplyStock||0)>0&&state.nationalFood>=125){const gain=Math.min(250,army.maxTroops-army.troops);army.troops+=gain;adjustComposition(army,{[army.unitType||'INFANTRY']:gain});state.nationalFood-=125}if(army.troops>=army.maxTroops)army.mustering=false}const d=domainInfo();if(d.over){const income=Math.max(0,state.nationalGold-previousGold),tax=Math.floor(income*.12*d.over);state.nationalGold=Math.max(0,state.nationalGold-tax);state.legitimacy=Math.max(0,state.legitimacy-2*d.over);addLog(`직할령 과부하 ${d.over}곳: 세수 ${tax}금 감소, 천명·민심 -${2*d.over}.`)} }
