const chooseArmyTypeV052=chooseArmyType;chooseArmyType=function(q,r){const tile=state.tiles[tileKey(q,r)];if(!tile?.node||tile.owner!==state.playerFaction||!tile.isCore)return addLog('평정이 끝난 자국 거점에서만 군단을 소집할 수 있습니다.');let dialog=document.getElementById('recruit-dialog');if(!dialog){dialog=document.createElement('dialog');dialog.id='recruit-dialog';document.body.append(dialog)}const allowed=Object.entries(UNIT_TYPES).filter(([id])=>['INFANTRY','ARCHER'].includes(id)||id.startsWith(state.playerFaction==='GOGURYEO'?'GOG_':`${state.playerFaction}_`));dialog.innerHTML=`<h2>군단 소집과 병종 편성</h2><p>처음에는 최대 병력의 45%만 모입니다. 보급이 닿으면 매 턴 충원됩니다.</p><div class="unit-choice-grid">${allowed.map(([id,u])=>`<button data-unit="${id}"><b>${u.label}</b><small>금 ${u.gold} · 군량 ${u.food} · 철 ${u.iron||0} · 말 ${u.horse||0} · 피해 ${u.damage} · 유지 ${u.toughness} · 추격 ${u.pursuit} · 차단 ${u.screen} · 공성 ${u.siege}</small><small>${u.description||''}</small></button>`).join('')}</div><button data-close>돌아가기</button>`;dialog.querySelectorAll('[data-unit]').forEach(button=>button.onclick=()=>{raiseNewArmyV052(q,r,button.dataset.unit);dialog.close()});dialog.querySelector('[data-close]').onclick=()=>dialog.close();dialog.showModal()};
function raiseNewArmyV052(q,r,type){const clan=activeClan(),tile=state.tiles[tileKey(q,r)],unit=UNIT_TYPES[type];if(!unit||tile?.owner!==state.playerFaction||!tile.node||!tile.isCore)return addLog('소집할 수 없는 거점입니다.');if(state.nationalGold<unit.gold||state.nationalFood<unit.food||state.iron<(unit.iron||0)||state.horses<(unit.horse||0))return addLog('병종 편성 자원이 부족합니다.');state.nationalGold-=unit.gold;state.nationalFood-=unit.food;state.iron-=unit.iron||0;state.horses-=unit.horse||0;state.armySeq++;const maxTroops=2000,troops=Math.floor(maxTroops*.45),commander=state.generals.find(g=>g.faction===state.playerFaction&&!state.armies.some(a=>a.commanderId===g.id||a.subCommanderId===g.id)&&g.id!==state.supremeCommanderId),composition={[type]:troops};const army={id:`a_${state.playerFaction.toLowerCase()}_${state.armySeq}`,name:`${clan.leader} ${unit.label} 소집군`,owner:state.playerFaction,clanId:clan.id,commanderId:commander?.id||null,subCommanderId:null,unitType:type,composition,q,r,troops,maxTroops,morale:85,supplied:true,ap:0,mustering:true,training:20};state.armies.push(army);state.selectedArmyId=army.id;addLog(`${army.name}이 ${troops}명으로 소집을 시작했습니다. 첫 턴은 정비하며 보급 시 매 턴 최대 450명까지 충원됩니다.`);markStateAction('army-raised');renderAll()}
