function chronicleDisplayText(value){const labels={HIGH:'경계를 문서로 명확히 규정함',LOW:'구두 맹약으로 실리를 택함',NONE:'맹약의 해석을 유보함',FULL:'한강 하류를 전부 취함',PARTIAL:'약속한 몫만 취함',DELEGATE:'현장 장수에게 결정을 맡김',DEFENSE:'산성망 청야 지구전',OFFENSE:'한강 이남 선제 도하',PACT:'신라에 비밀 밀사 파견',IGNORE:'침공을 감내함',PREEMPT:'선제 대응',CAPTURED:'성왕 생포',DIES:'성왕 전사',SPARED:'성왕 생환',PRESENT:'성왕 친정',ABSENT:'성왕 불참'};let text=String(value||'');if(text.startsWith('TREATY_clarity=')){const match=text.match(/TREATY_clarity=(HIGH|LOW|NONE).*?trust\s+(\d+)/);if(match)return`한강 맹약 ${match[1]==='HIGH'?'명문화':match[1]==='LOW'?'구두 합의':'해석 유보'}, 나제동맹 신뢰도 ${match[2]}`}if(text.startsWith('SILLA_raid_scope=')){const code=text.split('=')[1];return`신라의 한강 하류 취득 범위: ${labels[code]||'결정 확정'}`}if(text.startsWith('BAEKJE_response='))return`백제의 대응: ${labels[text.split('=')[1]]||'대응 확정'}`;if(text.startsWith('GWANSAN_outcome='))return`관산성 결전의 결과: ${labels[text.split('=')[1]]||'결전 결말 확정'}`;if(text.startsWith('CS-')&&text.includes('='))return`고구려의 방책: ${labels[text.split('=').at(-1)]||'전략 선택 확정'}`;if(text.startsWith('{')){try{const reward=JSON.parse(text),names={gold:'국고',troops:'병력',legitimacy:'천명·민심',trust:'동맹 신뢰',gayaBaekje:'대가야의 백제 호감',gayaSilla:'대가야의 신라 호감',pact:'고구려 밀약'};return Object.entries(reward).map(([key,v])=>`${names[key]||'보상'} ${v}`).join(' · ')}catch{}}return text.split(' / ').map(part=>labels[part]||part).join(' · ')}
function renderQuestCards(quests){let futureShown=false;return quests.map((quest,index)=>{const completed=state.quests.completed.has(quest.id),active=index===state.quests.mainIndex;if(!completed&&!active){if(futureShown)return'';futureShown=true;return`<div class="quest-card quest-blind"><b>${UI_LABELS.questUnknown}</b><p>${UI_LABELS.questUnknownDescription}</p></div>`}const history=(state.quests.history||[]).filter(entry=>entry.questId===quest.id),record=history.map(entry=>`<div class="quest-chronicle">✒️ 나의 역사 기록 · 제${entry.turn}턴: ${escapeHtml(chronicleDisplayText(entry.choice))} 선택 → ${escapeHtml(chronicleDisplayText(entry.result))}</div>`).join('');return`<div class="quest-card ${active?'active':''}"><b>${quest.id} · ${escapeHtml(quest.title)}</b><span class="quest-state">${completed?UI_LABELS.questDone:UI_LABELS.questActive}</span><p>${escapeHtml(quest.description)}</p>${active?`<p class="quest-objective">${questObjective(quest.id)}</p>`:''}${record}</div>`}).join('')}
const chronicleKoreanCoreV051=chronicle;chronicle=function(questId,choice,result){const choiceMap={PRESENT:'성왕이 직접 전장에 나선다',ABSENT:'성왕이 전장에 불참한다',KING_CAPTURED:'성왕을 사로잡는다',KING_DIES:'성왕이 전사한다',KING_SPARED:'성왕을 살려 보낸다'};const translatedChoice=String(choice).split(' / ').map(part=>choiceMap[part]||part).join(' · ');let text=String(result||'');if(text.startsWith('SILLA_raid_scope=')){const v=text.split('=')[1];text=`신라의 한강 하류 취득 범위: ${v==='FULL'?'전부 취함':v==='PARTIAL'?'약속한 몫만 취함':'결정 위임'}`}else if(text.startsWith('BAEKJE_response=')){const v=text.split('=')[1];text=`백제의 대응: ${v==='PREEMPT'?'선제 대응':v==='IGNORE'?'침공을 감내함':'장수에게 맡김'}`}else if(text.startsWith('GWANSAN_outcome=')){const v=text.split('=')[1];text=`관산성 결전의 결과: ${({KING_CAPTURED:'성왕 생포',KING_DIES:'성왕 전사',KING_SPARED:'성왕 생환',KING_ABSENT:'성왕 불참'})[v]||'결전 결말 확정'}`}else if(text.startsWith('CS-')&&text.includes('=')){const v=text.split('=').at(-1);text=`고구려의 방책: ${choiceMap[v]||({DEFENSE:'산성망에 의지한 청야 지구전',OFFENSE:'한강 이남 선제 도하',PACT:'신라에 비밀 밀사 파견'})[v]||'전략 선택 확정'}`}chronicleKoreanCoreV051(questId,translatedChoice,text)};
