function mergeArmiesOnTile(q,r){const tileArmies=state.armies.filter(army=>army.q===q&&army.r===r&&army.owner===state.playerFaction&&army.troops>50);let main=tileArmies.find(army=>army.id===state.selectedArmyId);if(!main)main=tileArmies[0];const status=armyMergeStatus(tileArmies,main);if(!status.eligible){addLog(status.reason);return}const stack=[main,...status.candidates],total=stack.reduce((sum,army)=>sum+army.troops,0),averages={morale:stack.reduce((sum,army)=>sum+(army.morale||0)*army.troops,0)/Math.max(1,total),supplyStock:stack.reduce((sum,army)=>sum+(army.supplyStock||0)*army.troops,0)/Math.max(1,total),training:stack.reduce((sum,army)=>sum+(army.training||0)*army.troops,0)/Math.max(1,total)};for(const army of stack.slice(1)){main.troops+=army.troops;main.maxTroops=(main.maxTroops||0)+(army.maxTroops||army.troops);for(const[type,count]of Object.entries(army.composition||{[army.unitType||'INFANTRY']:army.troops}))main.composition[type]=(main.composition[type]||0)+count;for(const slot of ['commanderId','subCommanderId'])if(!main[slot]&&army[slot]&&main.commanderId!==army[slot]&&main.subCommanderId!==army[slot])main[slot]=army[slot]}main.morale=Math.round(averages.morale);main.supplyStock=averages.supplyStock;main.supplyShortageTurns=Math.max(...stack.map(army=>army.supplyShortageTurns||0));main.training=Math.round(averages.training);main.ap=Math.min(...stack.map(army=>army.ap||0));const removed=new Set(stack.slice(1).map(army=>army.id));state.armies=state.armies.filter(army=>!removed.has(army.id));if(removed.has(state.movingArmyId))state.movingArmyId=null;state.selectedArmyId=main.id;updateSupplyLines(state);addLog(`${stack.length}개 군단을 ${main.name}으로 병합했습니다. 사기·보급은 병력 가중 평균, 행군력은 낮은 쪽 기준으로 정리했습니다.`);renderAll()}
function drawSelectedSupplyPath(){const army=state.armies.find(item=>item.id===state.selectedArmyId);if(!army?.supplyConnected||!army.supplyPath?.length)return;const dpr=window.devicePixelRatio||1,cam=state.camera;ctx.save();ctx.setTransform(dpr*cam.zoom,0,0,dpr*cam.zoom,dpr*cam.x,dpr*cam.y);ctx.strokeStyle='#22d3ee';ctx.fillStyle='#22d3ee';ctx.lineWidth=4/Math.max(.6,cam.zoom);ctx.setLineDash([8/Math.max(.6,cam.zoom),5/Math.max(.6,cam.zoom)]);ctx.beginPath();army.supplyPath.forEach((key,index)=>{const tile=state.tiles[key];if(!tile)return;const point=hexToPixel(tile.q,tile.r);if(index===0)ctx.moveTo(point.x,point.y);else ctx.lineTo(point.x,point.y)});ctx.stroke();ctx.setLineDash([]);for(const key of army.supplyPath){const tile=state.tiles[key];if(!tile)continue;const point=hexToPixel(tile.q,tile.r);ctx.beginPath();ctx.arc(point.x,point.y,5/Math.max(.6,cam.zoom),0,Math.PI*2);ctx.fill()}ctx.restore()}
